-- =============================================================================
-- 544 — LE CAHIER D'EXERCICES DE 1RE (partie 32)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 544 --niveau 1re --fichiers sciences-gestion-numerique.n1,sciences-sanitaires-sociales.n1,sciences-sanitaires-sociales.n2 --suffixe 32 > supabase/contenu/544_exercices_1re_32.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   sciences-gestion-numerique.n1  36 exercices · 12 chapitres
--   sciences-sanitaires-sociales.n1  24 exercices · 8 chapitres
--   sciences-sanitaires-sociales.n2  24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('8c70f435-bd3c-5ceb-9639-7cc9af5c6994'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une boulangerie, une piscine et un club de course","competence":"lire-tableau","situation":"Dans la petite ville de Vireloup, trois organisations rendent service aux habitants. Elles n’ont pas le même but ni le même propriétaire : un tableau permet de les comparer.","documents":[{"id":"orgas","type":"tableau","titre":"Trois organisations de Vireloup","source":"Organisations imaginées pour l’exercice.","colonnes":["Organisation","Qui la détient","Son but"],"lignes":[["Le Fournil de Zoé (boulangerie)","Zoé, seule","Vendre du pain et réaliser un profit"],["Piscine municipale","La commune","Rendre un service d’intérêt général à prix modéré"],["Association Les Foulées du lac","Ses 120 adhérents","Faire courir ses membres, sans partager de bénéfices"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui dit à qui appartient la piscine.","aide":"Regarde la ligne de la piscine, dans la colonne « Qui la détient ».","type":"zone","document":"orgas","multiple":false},{"enonce":"Associe chaque organisation à son type.","aide":"Le but indiqué dans le tableau suffit : profit, intérêt général ou service aux membres sans partage de bénéfices.","type":"association","gauche":[{"id":"g0","texte":"Le Fournil de Zoé"},{"id":"g1","texte":"Piscine municipale"},{"id":"g2","texte":"Association Les Foulées du lac"}],"droite":[{"id":"d0","texte":"Organisation à but non lucratif"},{"id":"d1","texte":"Entreprise privée"},{"id":"d2","texte":"Organisation publique"}]},{"enonce":"Dans l’association, chaque adhérent dispose d’une voix en assemblée générale. Combien de voix compte l’assemblée si tous les adhérents sont présents ?","aide":"Une personne, une voix : combien y a-t-il d’adhérents dans le tableau ?","type":"nombre","unite":"voix"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La piscine appartient à **la commune** : c’est une organisation publique, détenue par une collectivité."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le Fournil cherche un **profit** (entreprise privée), la piscine rend un service d’**intérêt général** (organisation publique), l’association ne partage **aucun bénéfice** (but non lucratif)."},{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120 voix","explication":"Dans une association, c’est le principe « une personne, une voix » : **120 adhérents, 120 voix**."}]$ex$::jsonb),
  ('8c70f435-bd3c-5ceb-9639-7cc9af5c6994'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La société anonyme Cyclo-Vallée tient son assemblée","competence":"analyser-document","situation":"Cyclo-Vallée fabrique des vélos de ville. C’est une société anonyme : ses 400 actionnaires ne dirigent pas eux-mêmes l’entreprise. Qui décide, et qui contrôle ?","documents":[{"id":"pouvoir","type":"chaine","disposition":"ligne","titre":"Qui détient le pouvoir de décision ?","source":"Schéma simplifié.","noeuds":[{"id":"z1","texte":"Actionnaires","emoji":"🧑‍💼"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Direction générale","emoji":"🏢"}],"liens":[{"de":"z1","a":"z2","texte":"élisent"},{"de":"z2","a":"z3","texte":"nomme"}]},{"id":"ag","type":"texte","genre":"article","titre":"Compte rendu de l’assemblée générale","source":"Texte écrit pour l’exercice ; entreprise imaginaire.","blocs":["Les 400 actionnaires de Cyclo-Vallée se réunissent en assemblée générale. Ils approuvent les comptes de l’année et élisent le conseil d’administration.","Le commissaire aux comptes déclare que les comptes sont sincères et réguliers.","Le directeur général, M. Barral, propose de réinvestir tout le bénéfice dans une nouvelle usine. Plusieurs actionnaires auraient préféré un dividende plus élevé."]}],"questions":[{"enonce":"Touche le mot qui désigne l’acteur chargé de certifier la sincérité des comptes.","aide":"Cherche, dans le deuxième paragraphe, la personne qui déclare les comptes sincères.","type":"zone","document":"ag","multiple":false},{"enonce":"Quel organe se cache derrière le point d’interrogation du schéma, entre les actionnaires et la direction générale ?","aide":"Les actionnaires élisent cet organe, qui nomme ensuite la direction générale.","type":"choix","options":[{"id":"a","texte":"Le conseil d’administration"},{"id":"b","texte":"Le bureau de l’association"},{"id":"c","texte":"Le commissaire aux comptes"},{"id":"d","texte":"La Cour des comptes"}],"multiple":false},{"enonce":"Associe chaque acteur à son rôle dans la société anonyme.","aide":"Relis le compte rendu et le schéma : l’un élit, l’autre nomme, un troisième certifie.","type":"association","gauche":[{"id":"g0","texte":"Assemblée générale"},{"id":"g1","texte":"Conseil d’administration"},{"id":"g2","texte":"Commissaire aux comptes"},{"id":"g3","texte":"Direction générale"}],"droite":[{"id":"d0","texte":"Dirige l’entreprise au quotidien"},{"id":"d1","texte":"Certifie la sincérité des comptes"},{"id":"d2","texte":"Nomme la direction générale"},{"id":"d3","texte":"Approuve les comptes et peut révoquer les dirigeants"}]},{"enonce":"Pourquoi M. Barral et certains actionnaires ne sont-ils pas d’accord sur l’usage du bénéfice ?","aide":"Un dividende rémunère l’actionnaire ; une nouvelle usine fait grandir l’entreprise.","type":"choix","options":[{"id":"a","texte":"Le directeur privilégie la croissance, des actionnaires la rentabilité de leurs titres"},{"id":"b","texte":"Le directeur veut réduire le capital, les actionnaires veulent plus de salariés"},{"id":"c","texte":"Le directeur veut moins de contrôle, les actionnaires veulent moins de dividendes"},{"id":"d","texte":"Le directeur veut plus de dividendes, les actionnaires veulent de la croissance"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Le **commissaire aux comptes** certifie que les comptes sont sincères. C’est un contrôle extérieur aux dirigeants."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans une société anonyme, les actionnaires élisent **le conseil d’administration**, qui nomme la direction générale."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"L’**assemblée générale** approuve les comptes et peut révoquer ; le **conseil d’administration** nomme la direction ; le **commissaire** certifie les comptes ; la **direction générale** dirige."},{"cle":{"type":"choix","ids":["a"]},"explication":"Propriétaires et dirigeants sont des personnes différentes : leurs intérêts peuvent diverger. Le dirigeant vise la **croissance**, l’actionnaire la **rentabilité de ses titres**."}]$ex$::jsonb),
  ('8c70f435-bd3c-5ceb-9639-7cc9af5c6994'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Verger & Fils contre Les Vergers Unis","competence":"raisonner","situation":"Deux organisations vendent des pommes : une société par actions et une coopérative. Qui y détient le pouvoir, et le contrôle du dirigeant pose-t-il le même problème dans les deux ?","documents":[{"id":"tab","type":"tableau","titre":"Deux façons de gouverner","source":"Organisations imaginées pour l’exercice.","colonnes":["Critère","SA Verger & Fils","Coopérative Les Vergers Unis"],"lignes":[["Qui détient l’organisation ?","1 000 actions : le fonds Orme en détient 450, Mme Rey 300 et 250 petits actionnaires 1 chacun","300 coopérateurs, producteurs de pommes"],["Règle de vote","Une action, une voix","Une personne, une voix"],["Direction","Un conseil élu par les actionnaires nomme la direction générale","Un conseil élu par les coopérateurs nomme un directeur salarié"],["Résultat","Dividendes versés aux actionnaires","Excédents répartis entre les coopérateurs"]],"enteteLignes":true},{"id":"mail","type":"texte","genre":"lettre","titre":"Courriel d’une petite actionnaire","source":"Courriel écrit pour l’exercice.","blocs":["Objet : assemblée générale de Verger & Fils","Bonjour, je possède une seule action et je ne peux pas me déplacer à l’assemblée. De toute façon, ma voix ne pèse presque rien face au fonds Orme. Je ne sais pas si le directeur utilise bien l’argent des actionnaires. Lina Perret"]}],"questions":[{"enonce":"Touche la case qui dit comment votent les coopérateurs.","aide":"Cherche la ligne « Règle de vote », colonne de la coopérative.","type":"zone","document":"tab","multiple":false},{"enonce":"À Verger & Fils, il faut plus de la moitié des voix pour imposer une décision. Combien d’actions de plus le fonds Orme doit-il acquérir pour y parvenir ?","aide":"La moitié de 1 000 est 500 : il faut dépasser 500, donc détenir au moins 501 actions.","type":"nombre","unite":"actions"},{"enonce":"Que montre le courriel de Lina Perret sur la gouvernance de Verger & Fils ?","aide":"Lina possède 1 action sur 1 000 : que peut-elle surveiller ?","type":"choix","options":[{"id":"a","texte":"Le dirigeant a été révoqué par une assemblée sans que les actionnaires soient informés"},{"id":"b","texte":"Le conseil d’administration a été élu par les salariés et non par les actionnaires"},{"id":"c","texte":"Les actionnaires ont refusé de nommer un commissaire pour certifier les comptes"},{"id":"d","texte":"La propriété dispersée rend le contrôle du dirigeant difficile pour les petits actionnaires"}],"multiple":false},{"enonce":"Dans la coopérative, combien de voix faut-il au minimum pour obtenir la majorité absolue lors d’un vote où les 300 coopérateurs sont présents ?","aide":"Une voix par coopérateur : il faut dépasser la moitié de 300.","type":"nombre","unite":"voix"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Chez les coopérateurs, c’est **une personne, une voix**, quel que soit l’apport ; dans la société par actions, une action donne une voix."},{"cle":{"type":"nombre","valeur":51,"tolerance":0},"affichage":"51 actions","explication":"La majorité absolue est de **501 voix** (plus de la moitié de 1 000). Le fonds en a 450 : il lui manque 501 − 450 = **51 actions**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Plus la propriété est **dispersée**, plus le contrôle des dirigeants est un enjeu : une petite actionnaire pèse peu et surveille mal."},{"cle":{"type":"nombre","valeur":151,"tolerance":0},"affichage":"151 voix","explication":"La moitié de 300 est 150 : il faut **151 voix** au moins. Aucun apport, même énorme, ne donne plus d’une voix."}]$ex$::jsonb),
  ('0c6cd590-fdd4-52aa-ac67-7a08e7513e93'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le premier service de Malik à la boulangerie","competence":"analyser-texte","situation":"Malik, 17 ans, fait son stage de première dans une boulangerie. Son tuteur note ce qu’il observe pour comprendre ce qui se passe dans la tête du stagiaire et ce qui se voit.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le carnet du tuteur","source":"Texte écrit pour l’exercice.","blocs":["Malik, timide et méthodique, a le trac avant son premier service. Il arrive dix minutes en avance et range le comptoir sans qu’on le lui demande.","Face à une cliente pressée qui s’énerve, il garde son calme et sourit. Il la juge pourtant odieuse. Yasmine, sa collègue, pense seulement que la cliente est fatiguée."]}],"questions":[{"enonce":"Touche le mot qui annonce un comportement que le tuteur peut observer.","aide":"Un comportement est ce que la personne fait, visible de l’extérieur.","type":"zone","document":"recit","multiple":false},{"enonce":"Associe chaque notion à l’élément du carnet qui l’illustre.","aide":"La perception est la manière de lire une même situation : ici, deux lectures différentes.","type":"association","gauche":[{"id":"g0","texte":"Personnalité"},{"id":"g1","texte":"Émotion"},{"id":"g2","texte":"Contrôle de soi"},{"id":"g3","texte":"Perception"}],"droite":[{"id":"d0","texte":"Le trac avant le premier service"},{"id":"d1","texte":"Malik juge la cliente odieuse, Yasmine la juge fatiguée"},{"id":"d2","texte":"Timide et méthodique"},{"id":"d3","texte":"Rester calme face à une cliente qui s’énerve"}]},{"enonce":"Malik et Yasmine voient la même cliente, mais en font des lectures opposées. Quelle notion l’explique le mieux ?","aide":"Chacun sélectionne et interprète les informations à sa manière.","type":"choix","options":[{"id":"a","texte":"La structure de propriété"},{"id":"b","texte":"Le niveau de qualification"},{"id":"c","texte":"La perception de chacun"},{"id":"d","texte":"Le canal de communication"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"Arriver en avance est un **comportement** : on le voit. Le trac, lui, est une émotion que l’on ne voit pas directement."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"La **personnalité** est un ensemble de traits stables, l’**émotion** une réaction brève, le **contrôle de soi** la maîtrise de ses réactions, la **perception** une interprétation propre à chacun."},{"cle":{"type":"choix","ids":["c"]},"explication":"Deux personnes peuvent vivre la même scène différemment : c’est la **perception**, manière de sélectionner et d’interpréter l’information."}]$ex$::jsonb),
  ('0c6cd590-fdd4-52aa-ac67-7a08e7513e93'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un message qui n’arrive pas jusqu’à Hugo","competence":"analyser-document","situation":"Inès, responsable d’un magasin de sport, écrit à Hugo, apprenti depuis une semaine. Le message est lu, mais la tâche n’est pas faite. Où la communication a-t-elle cloché ?","documents":[{"id":"sms","type":"dialogue","modele":"sms","source":"Échange écrit pour l’exercice.","participants":[{"nom":"Inès","emoji":"👩‍💼","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Hugo, tu me fais un reporting des KPI avant 17 h ?"},{"qui":"Hugo","texte":"Euh… je ne vois pas de quoi tu parles. Tu peux m’expliquer ?"}]},{"id":"schema","type":"chaine","disposition":"cycle","titre":"Le schéma de la communication","source":"Schéma simplifié.","noeuds":[{"id":"z1","texte":"Émetteur : Inès","emoji":"🗣️"},{"id":"z2","texte":"?","emoji":"📱"},{"id":"z3","texte":"Récepteur : Hugo","emoji":"👂"},{"id":"z4","texte":"Rétroaction","emoji":"↩️"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]}],"questions":[{"enonce":"Touche les deux mots d’Inès qui jouent le rôle de bruit pour Hugo.","aide":"Quels mots techniques un apprenti de première semaine peut-il ne pas connaître ?","type":"zone","document":"sms","multiple":true},{"enonce":"Quel canal Inès utilise-t-elle pour transmettre son message (le point d’interrogation du schéma) ?","aide":"Regarde la forme du document 1 : des messages qui s’affichent.","type":"choix","options":[{"id":"a","texte":"Une réunion en face à face"},{"id":"b","texte":"Un appel de visioconférence"},{"id":"c","texte":"Une affiche dans l’arrière-boutique"},{"id":"d","texte":"Un échange écrit sur messagerie instantanée"}],"multiple":false},{"enonce":"Que montre la réponse d’Hugo, « Tu peux m’expliquer ? » ?","aide":"Dans le schéma, quel maillon permet au récepteur de montrer ce qu’il a compris ?","type":"choix","options":[{"id":"a","texte":"Il envoie un nouveau message sans réponse attendue"},{"id":"b","texte":"Il change le code du message : c’est un bruit"},{"id":"c","texte":"Il refuse de travailler : c’est un conflit ouvert"},{"id":"d","texte":"Il signale qu’il n’a pas compris : c’est la rétroaction"}],"multiple":false},{"enonce":"Range chaque idée : bruit qui gêne la transmission ou façon de l’améliorer ?","aide":"Un bruit perturbe la transmission ; une amélioration aide le récepteur à comprendre.","type":"categories","categories":[{"id":"c0","texte":"Bruit qui gêne"},{"id":"c1","texte":"Façon d’améliorer"}],"items":[{"id":"i0","texte":"La fatigue d’Hugo en fin de journée"},{"id":"i1","texte":"Définir chaque sigle dans le message"},{"id":"i2","texte":"Les sigles non expliqués"},{"id":"i3","texte":"Demander à Hugo de reformuler la consigne"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m7"]},"explication":"Le **jargon** (« reporting », « KPI ») est un bruit : Hugo ne connaît pas ces mots, le message est mal décodé."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le canal est le moyen de transmission : ici une **messagerie instantanée**, sans le ton ni les gestes de l’oral."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **rétroaction** (feedback) permet au récepteur de montrer qu’il a — ou n’a pas — compris. Elle donne à Inès l’occasion de corriger."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Jargon et fatigue sont des **bruits**. Expliquer les sigles et faire reformuler sont deux moyens d’**améliorer** la communication."}]$ex$::jsonb),
  ('0c6cd590-fdd4-52aa-ac67-7a08e7513e93'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Jade cherche une alternance : que dit sa trace en ligne ?","competence":"analyser-document","situation":"Jade Morel, étudiante en BTS, postule à une alternance d’assistante commerciale. Avant l’entretien, la recruteuse tape son nom dans un moteur de recherche et lit l’offre qu’elle a elle-même publiée.","documents":[{"id":"recherche","type":"tableau","titre":"Ce que montre une recherche sur « Jade Morel »","source":"Résultats imaginés pour l’exercice.","colonnes":["Résultat","Où le trouve-t-on ?"],"lignes":[["Profil : étudiante en BTS, alternance recherchée","Réseau professionnel"],["Photo de soirée, verre à la main, en accès public","Compte personnel"],["Commentaire insultant sous une vidéo de jeu","Forum"],["Bénévole au club de handball de Pontlieue","Site du club"]],"enteteLignes":true},{"id":"offre","type":"fiche","modele":"affiche","entete":"Alternance : assistant(e) commercial(e)","sousTitre":"Magasin Sport’Nord","emoji":"📌","lignes":[{"texte":"Missions","valeur":"accueillir les clients, saisir les commandes"},{"texte":"Savoirs","valeur":"notions de gestion commerciale"},{"texte":"Savoir-faire","valeur":"construire un tableau de suivi sur tableur"},{"texte":"Savoir-être","valeur":"esprit d’équipe, calme face à un client mécontent"}],"pied":"Offre écrite pour l’exercice."}],"questions":[{"enonce":"Touche les deux résultats qui risquent de donner une mauvaise image de Jade à un recruteur.","aide":"Pense à ce qu’un recruteur attend d’une future assistante commerciale face aux clients.","type":"zone","document":"recherche","multiple":true},{"enonce":"Complète la définition.","aide":"Ce qu’on publie, commente ou partage laisse des marques ; l’adjectif dit qu’on parle du monde en ligne.","type":"trous","segments":["L’ensemble des ",0," qu’une personne laisse en ligne s’appelle son identité ",1,"."],"banque":["adresses","numérique","traces","sociale"]},{"enonce":"Quelles deux actions de Jade respecteraient les bonnes pratiques de gestion de son identité numérique ?","aide":"Deux gestes protègent la vie privée et réparent la trace ; les autres l’aggravent.","type":"choix","options":[{"id":"a","texte":"Créer un faux profil professionnel au nom d’une amie"},{"id":"b","texte":"Publier plus de photos de soirée pour paraître sociable"},{"id":"c","texte":"Mélanger vie privée et vie professionnelle sur un seul compte"},{"id":"d","texte":"Supprimer son commentaire et le signaler comme une erreur"},{"id":"e","texte":"Paramétrer la confidentialité de son compte personnel"}],"multiple":true},{"enonce":"D’après l’offre, range chaque exemple de compétence en savoir, savoir-faire ou savoir-être.","aide":"Savoir = connaissances ; savoir-faire = geste ou technique ; savoir-être = attitude.","type":"categories","categories":[{"id":"c0","texte":"Savoir"},{"id":"c1","texte":"Savoir-faire"},{"id":"c2","texte":"Savoir-être"}],"items":[{"id":"i0","texte":"Connaître les étapes d’une vente"},{"id":"i1","texte":"Garder son calme face à un client mécontent"},{"id":"i2","texte":"Connaître la différence entre un devis et une facture"},{"id":"i3","texte":"Saisir sans erreur une commande sur un tableur"},{"id":"i4","texte":"Construire un tableau de suivi des commandes"},{"id":"i5","texte":"Écouter un client sans l’interrompre"}]},{"enonce":"Touche le résultat qui prouve le mieux le savoir-être « esprit d’équipe » demandé dans l’offre.","aide":"Quel résultat parle d’un engagement avec d’autres personnes ?","type":"zone","document":"recherche","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r2c0"]},"explication":"La **photo de soirée publique** et le **commentaire insultant** nuisent à son image professionnelle : tout ce qui est en ligne y reste."},{"cle":{"type":"trous","trous":[["traces"],["numerique"]]},"affichage":"traces · numérique","explication":"L’**identité numérique** est l’ensemble des **traces** qu’on laisse en ligne : profils, publications, photos, commentaires."},{"cle":{"type":"choix","ids":["d","e"]},"explication":"Régler la **confidentialité** et retirer ce qui dessert son image sont de bonnes pratiques ; séparer vie privée et vie professionnelle va dans le même sens."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c1","i4":"c1","i5":"c2"}},"explication":"Les **savoirs** se connaissent, les **savoir-faire** se réalisent, les **savoir-être** se manifestent dans la relation aux autres."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le **bénévolat dans un club de handball** montre qu’elle sait travailler avec d’autres : c’est une trace utile à sa candidature."}]$ex$::jsonb),
  ('e42d9492-3c55-5e95-8129-32cbb7a1f4f3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les habitudes du club de basket de Saint-Aubin","competence":"analyser-texte","situation":"Léa vient d’arriver au club de basket de Saint-Aubin. Elle découvre vite que le club a ses façons de faire, écrites ou non.","documents":[{"id":"club","type":"texte","genre":"recit","titre":"Le premier mois de Léa","source":"Texte écrit pour l’exercice ; club imaginaire.","blocs":["Ici, tout le monde se tutoie, même le président. Après chaque match, les joueurs partagent le goûter du samedi, une habitude vieille de vingt ans.","Les anciens répètent que « les jeunes ne pensent qu’à leur téléphone ». Nour, 16 ans, capitaine de l’équipe, trouve cela injuste. Chaque semaine, elle retrouve son amie Inès pour s’entraîner, sans que personne le leur demande."]}],"questions":[{"enonce":"Touche le mot qui annonce la pratique répétée qui est un rituel du club.","aide":"Un rituel est une pratique répétée dans le temps, comme une tradition.","type":"zone","document":"club","multiple":false},{"enonce":"Associe chaque élément du texte à la notion de la culture d’organisation qu’il illustre.","aide":"Une norme est une règle de conduite ; un statut est une position dans le groupe.","type":"association","gauche":[{"id":"g0","texte":"Se tutoyer, même avec le président"},{"id":"g1","texte":"Le goûter du samedi après le match"},{"id":"g2","texte":"« Les jeunes ne pensent qu’à leur téléphone »"},{"id":"g3","texte":"Nour est capitaine de l’équipe"}],"droite":[{"id":"d0","texte":"Une norme"},{"id":"d1","texte":"Un statut"},{"id":"d2","texte":"Un stéréotype"},{"id":"d3","texte":"Un rituel"}]},{"enonce":"Nour et Inès s’entraînent ensemble sans que personne le leur demande. Cette relation est…","aide":"Personne ne l’a imposée : elle naît de l’amitié.","type":"choix","options":[{"id":"a","texte":"contractuelle : elle est fixée par le règlement du club"},{"id":"b","texte":"formelle : elle est prévue par l’organigramme et les procédures"},{"id":"c","texte":"hiérarchique : l’une rend compte à l’autre de ses résultats"},{"id":"d","texte":"informelle : elle est spontanée, non prévue par l’organisation"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"Le **goûter du samedi** est un rituel : une pratique répétée, partagée par les membres, qui crée du lien."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"Le tutoiement est une **norme**, le goûter un **rituel**, l’idée sur les jeunes un **stéréotype**, la place de capitaine un **statut**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une relation **informelle** est spontanée (amitié, entraide). Elle n’est ni prévue par l’organigramme ni imposée par une procédure."}]$ex$::jsonb),
  ('e42d9492-3c55-5e95-8129-32cbb7a1f4f3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’atelier de vélos : qui commande, vers qui va-t-on ?","competence":"observer-schema","situation":"Dans l’atelier Roue Libre, la directrice Mme Aubry a confié l’équipe à Paul, chef d’atelier. Mais quand une panne résiste, ce n’est pas toujours à lui qu’on s’adresse.","documents":[{"id":"orga","type":"schema","largeur":340,"hauteur":290,"titre":"Qui rend compte à qui ?","source":"Organisation imaginée pour l’exercice.","elements":[{"forme":"rect","x":85,"y":10,"l":170,"h":38,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Mme Aubry, directrice","id":"z1","zone":true},{"forme":"ligne","de":[170,48],"a":[170,88],"fleche":"fin"},{"forme":"rect","x":85,"y":88,"l":170,"h":38,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Paul, chef d’atelier","id":"z2","zone":true},{"forme":"ligne","de":[140,126],"a":[46,176],"fleche":"fin"},{"forme":"ligne","de":[170,126],"a":[170,176],"fleche":"fin"},{"forme":"ligne","de":[200,126],"a":[294,176],"fleche":"fin"},{"forme":"rect","x":8,"y":176,"l":76,"h":38,"arrondi":8,"teinte":"gris","motif":"clair","texte":"Sami","id":"z3","zone":true},{"forme":"rect","x":132,"y":176,"l":76,"h":38,"arrondi":8,"teinte":"gris","motif":"clair","texte":"Lou","id":"z4","zone":true},{"forme":"rect","x":256,"y":176,"l":76,"h":38,"arrondi":8,"teinte":"gris","motif":"clair","texte":"Inès","id":"z5","zone":true},{"forme":"ligne","de":[84,200],"a":[132,200],"fleche":"fin","style":"pointilles","teinte":"corail"},{"forme":"ligne","de":[256,200],"a":[208,200],"fleche":"fin","style":"pointilles","teinte":"corail"},{"forme":"texte","x":108,"y":192,"texte":"conseil","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":232,"y":192,"texte":"conseil","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":20,"y":252,"texte":"Trait plein : relation hiérarchique","taille":"petit","ancre":"debut"},{"forme":"texte","x":20,"y":270,"texte":"Trait pointillé : on vient demander conseil","taille":"petit","ancre":"debut"}]}],"questions":[{"enonce":"Touche la personne dont Sami reçoit directement ses ordres.","aide":"Suis le trait plein qui arrive au-dessus de Sami.","type":"zone","document":"orga","multiple":false},{"enonce":"Touche la mécanicienne vers laquelle ses collègues se tournent pour demander conseil.","aide":"Regarde où arrivent les flèches en pointillé.","type":"zone","document":"orga","multiple":false},{"enonce":"Paul donne des ordres, Lou entraîne les autres par son expérience. Quelle formule décrit le mieux la situation ?","aide":"L’autorité est reconnue comme légitime par la fonction ; le leadership vient de la capacité à entraîner.","type":"choix","options":[{"id":"a","texte":"Paul et Lou ont tous deux une autorité légitime sur l’équipe"},{"id":"b","texte":"Paul a l’autorité par sa fonction, Lou a de l’influence par sa personne"},{"id":"c","texte":"Ni Paul ni Lou n’exercent de pouvoir sur le reste de l’équipe"},{"id":"d","texte":"Paul a de l’influence par sa personne, Lou a l’autorité par sa fonction"}],"multiple":false},{"enonce":"Associe chaque situation de l’atelier à la notion correspondante.","aide":"L’incitation est le levier que l’organisation actionne : prime, promotion.","type":"association","gauche":[{"id":"g0","texte":"Paul fixe le planning de la semaine"},{"id":"g1","texte":"Lou donne l’exemple et on la suit"},{"id":"g2","texte":"Une prime est versée si l’atelier dépasse ses objectifs"},{"id":"g3","texte":"Deux mécaniciens se disputent un planning puis s’accordent sur une alternance"}],"droite":[{"id":"d0","texte":"Leadership"},{"id":"d1","texte":"Consensus"},{"id":"d2","texte":"Autorité"},{"id":"d3","texte":"Incitation"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Sami dépend directement de **Paul**, son supérieur hiérarchique : c’est une relation formelle, prévue par l’organisation."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**Lou** n’a aucun titre de chef, mais ses collègues viennent la consulter : c’est un leadership informel."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un chef a de l’**autorité** par sa fonction, un leader a de l’**influence** par sa personne. Le meilleur manager cumule les deux."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"L’**autorité** est un pouvoir légitime, le **leadership** un pouvoir d’entraînement, l’**incitation** un levier (prime), le **consensus** l’issue d’un conflit bien géré."}]$ex$::jsonb),
  ('e42d9492-3c55-5e95-8129-32cbb7a1f4f3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Sacha, nouveau responsable du rayon plantes","competence":"analyser-document","situation":"Sacha, 25 ans, vient d’être nommé responsable du rayon plantes d’une jardinerie. Mina, dix ans d’ancienneté, ne cache pas son scepticisme. Une fiche de poste et un échange de messages racontent la suite.","documents":[{"id":"poste","type":"fiche","modele":"affiche","entete":"Fiche de poste : responsable de rayon","sousTitre":"Jardinerie Les Trois Saules","emoji":"🪴","lignes":[{"texte":"Organiser les plannings du rayon","id":"z1"},{"texte":"Rend compte à la directrice du magasin","id":"z2"},{"texte":"Prime de 300 € si l’objectif trimestriel est atteint","id":"z3"}],"pied":"Fiche écrite pour l’exercice."},{"id":"echange","type":"dialogue","modele":"sms","source":"Échange écrit pour l’exercice.","participants":[{"nom":"Mina","emoji":"👩‍🌾","cote":"gauche"},{"nom":"Sacha","emoji":"🧑‍💼","cote":"droite"},{"nom":"Tom","emoji":"🧑","cote":"gauche"}],"repliques":[{"qui":"Mina","texte":"Encore un jeune chef qui ne pense qu’aux chiffres. Le planning de samedi a changé sans que personne ne soit consulté."},{"qui":"Sacha","texte":"Tu as raison, j’aurais dû vous en parler. Je propose qu’on fixe le planning ensemble chaque lundi."},{"qui":"Mina","texte":"Ça me va."},{"qui":"Tom","texte":"Moi, je fais comme Mina : c’est elle qui sait."}]}],"questions":[{"enonce":"Touche la ligne de la fiche de poste qui est une incitation.","aide":"Une incitation est un levier que l’organisation actionne pour pousser à agir.","type":"zone","document":"poste","multiple":false},{"enonce":"Touche la ligne qui décrit une relation formelle, prévue par l’organigramme.","aide":"Cherche le lien hiérarchique : à qui Sacha doit-il rendre des comptes ?","type":"zone","document":"poste","multiple":false},{"enonce":"Remets dans l’ordre les étapes de la gestion de ce conflit.","aide":"Gérer un conflit : écouter chaque partie, identifier le vrai problème, chercher une solution acceptable.","type":"ordre","items":[{"id":"a","texte":"Mina accepte la solution : c’est un consensus"},{"id":"b","texte":"Mina exprime son désaccord sur le planning"},{"id":"c","texte":"Sacha reconnaît le problème et écoute"},{"id":"d","texte":"Sacha propose un planning fixé ensemble chaque lundi"}]},{"enonce":"D’après les messages, qui exerce un leadership dans le rayon ?","aide":"Le leadership peut exister sans position hiérarchique : qui entraîne Tom ?","type":"choix","options":[{"id":"a","texte":"Sacha, parce qu’il a une position hiérarchique dans le rayon"},{"id":"b","texte":"Tom, parce qu’il suit les consignes de la directrice"},{"id":"c","texte":"La directrice, qui anime directement toutes les réunions"},{"id":"d","texte":"Mina, que Tom suit sans qu’elle ait d’autorité hiérarchique"}],"multiple":false}]}$ex$::jsonb,
