  ('83595a40-a9fe-549d-a2a0-5a8ec127fbd2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le bulletin de paie de Samia","competence":"lire-tableau","situation":"Samia est vendeuse au Fournil de Zoé. Elle veut comprendre pourquoi la somme qui arrive sur son compte est plus petite que le salaire écrit sur son contrat.","documents":[{"id":"bulletin","type":"fiche","modele":"ticket","entete":"Le Fournil de Zoé","sousTitre":"Bulletin de paie simplifié","emoji":"🧾","lignes":[{"texte":"Emploi","valeur":"vendeuse"},{"texte":"Qualification","valeur":"CAP employé de commerce"},{"separateur":true},{"texte":"Salaire brut","valeur":"2 000 €","id":"z1"},{"texte":"Cotisations salariales","valeur":"22 % du brut","id":"z2"},{"texte":"Salaire net","valeur":"?","gras":true,"id":"z3"}],"pied":"Bulletin imaginé pour l’exercice ; taux simplifié."}],"questions":[{"enonce":"Touche la ligne qui indique le salaire prévu au contrat de Samia.","aide":"Le salaire prévu au contrat est celui d’avant tout prélèvement.","type":"zone","document":"bulletin","multiple":false},{"enonce":"Quel est le montant des cotisations salariales de Samia, en euros ?","aide":"Calcule 22 % de 2 000 : 2 000 × 0,22.","type":"nombre","unite":"€"},{"enonce":"Associe chaque mention à ce qu’elle décrit chez Samia.","aide":"La qualification est attestée par un diplôme ; la compétence se prouve en situation de travail.","type":"association","gauche":[{"id":"g0","texte":"Le CAP indiqué sur le bulletin"},{"id":"g1","texte":"Tenir seule la caisse un jour d’affluence"}],"droite":[{"id":"d0","texte":"Une compétence"},{"id":"d1","texte":"Une qualification"}]},{"enonce":"Quel est le salaire net de Samia, en euros ?","aide":"Salaire brut moins cotisations salariales.","type":"nombre","unite":"€"}]}$ex$::jsonb,
