  ('83595a40-a9fe-549d-a2a0-5a8ec127fbd2'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Combien coûte un comptable à la PME Roue Libre ?","competence":"calculer","situation":"La PME Roue Libre emploie un comptable. Sa gérante veut savoir ce qu’il lui coûte vraiment sur l’année, et le comparer à ce qu’il produit.","documents":[{"id":"contrat","type":"fiche","modele":"ticket","entete":"PME Roue Libre","sousTitre":"Coût mensuel d’un salarié","emoji":"🚲","lignes":[{"texte":"Salaire brut","valeur":"2 500 €","id":"z1"},{"texte":"Cotisations patronales","valeur":"40 % du brut","id":"z2"},{"separateur":true},{"texte":"Coût global","valeur":"brut + patronales","gras":true}],"pied":"Taux simplifié, chiffres imaginés pour l’exercice."},{"id":"activite","type":"tableau","titre":"Activité du comptable sur l’année","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Valeur"],"lignes":[["Dossiers traités","3 000"],["Heures travaillées","1 500"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui indique ce que l’employeur paie en plus du salaire brut.","aide":"Ce sont des cotisations versées par l’employeur, pas par le salarié.","type":"zone","document":"contrat","multiple":false},{"enonce":"Quel est le coût du comptable pour l’employeur sur une année, en euros ?","aide":"Coût mensuel = 2 500 + 40 % de 2 500, puis multiplie par 12.","type":"nombre","unite":"€"},{"enonce":"Quelle valeur représente la productivité du comptable, en dossiers par heure ?","aide":"Productivité = production ÷ quantité de travail.","type":"choix","options":[{"id":"a","texte":"0,5 dossier par heure"},{"id":"b","texte":"2 dossiers par heure"},{"id":"c","texte":"3 000 dossiers par heure"},{"id":"d","texte":"1 500 dossiers par heure"}],"multiple":false},{"enonce":"Quel est le coût du travail par dossier traité, en euros ?","aide":"Divise le coût annuel par le nombre de dossiers de l’année.","type":"nombre","unite":"€"},{"enonce":"Un collègue, payé 2 800 € bruts, coûte 47 040 € par an et traite 4 000 dossiers. Comparé au premier comptable, il…","aide":"Calcule son coût par dossier : 47 040 ÷ 4 000.","type":"choix","options":[{"id":"a","texte":"coûte autant par dossier mais plus cher à l’année"},{"id":"b","texte":"coûte plus cher à l’année et plus cher par dossier"},{"id":"c","texte":"coûte plus cher à l’année mais moins cher par dossier"},{"id":"d","texte":"coûte moins cher à l’année et moins cher par dossier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Les **cotisations patronales** s’ajoutent au brut : elles font partie du coût du travail pour l’employeur."},{"cle":{"type":"nombre","valeur":42000,"tolerance":0},"affichage":"42 000 €","explication":"Cotisations patronales : 2 500 × 0,40 = 1 000 €. Coût mensuel : 3 500 €. Sur 12 mois : **42 000 €**."},{"cle":{"type":"choix","ids":["b"]},"explication":"3 000 dossiers ÷ 1 500 heures = **2 dossiers par heure**."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 €","explication":"42 000 ÷ 3 000 = **14 €** par dossier : le coût n’a de sens que rapporté à ce que le travail produit."},{"cle":{"type":"choix","ids":["c"]},"explication":"47 040 ÷ 4 000 = **11,76 € par dossier**, contre 14 €. Un salarié mieux payé mais plus productif peut coûter moins par unité produite."}]$ex$::jsonb),
  ('83595a40-a9fe-549d-a2a0-5a8ec127fbd2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les Ateliers du Marais ont-ils bien investi dans le bien-être ?","competence":"analyser-document","situation":"L’entreprise Les Ateliers du Marais a investi pour améliorer les conditions de travail de ses 80 salariés. La DRH veut vérifier, chiffres en main, que l’opération a payé.","documents":[{"id":"bord","type":"tableau","titre":"Tableau de bord social","source":"Chiffres imaginés pour l’exercice ; entreprise imaginaire.","colonnes":["Donnée","2023","2024"],"lignes":[["Effectif moyen","80","80"],["Entrées dans l’année","12","6"],["Sorties dans l’année","14","6"],["Heures théoriques de travail","128 000","128 000"],["Heures d’absence","6 400","3 520"]],"enteteLignes":true},{"id":"note","type":"texte","genre":"lettre","titre":"Note de la DRH","source":"Note écrite pour l’exercice.","blocs":["En 2024, l’entreprise a investi 40 000 € dans des sièges ergonomiques et des horaires plus souples. Une heure d’absence coûte en moyenne 25 € à l’entreprise (salaire versé et organisation perturbée)."]}],"questions":[{"enonce":"Touche la case qui, avec les heures théoriques de travail, permet de calculer le taux d’absentéisme de 2024.","aide":"Le taux d’absentéisme rapporte des heures d’absence aux heures théoriques.","type":"zone","document":"bord","multiple":false},{"enonce":"Quel était le taux d’absentéisme en 2023, en pourcentage ?","aide":"Heures d’absence ÷ heures théoriques × 100, avec les chiffres de 2023.","type":"nombre","unite":"%"},{"enonce":"Quelle lecture des chiffres de 2023 à 2024 est la plus cohérente avec la note de la DRH ?","aide":"Compare les entrées, les sorties et les heures d’absence d’une année sur l’autre.","type":"choix","options":[{"id":"a","texte":"De meilleures conditions de travail ont réduit l’absentéisme et le départ de salariés"},{"id":"b","texte":"La rotation du personnel a augmenté car moins de salariés sont entrés"},{"id":"c","texte":"L’investissement n’a eu aucun effet : l’effectif moyen est resté stable"},{"id":"d","texte":"La baisse de l’absentéisme vient d’une hausse du nombre d’heures théoriques"}],"multiple":false},{"enonce":"Quel est le taux de rotation du personnel en 2024, en pourcentage ? (rotation = ((entrées + sorties) ÷ 2) ÷ effectif moyen × 100)","aide":"Entrées et sorties de 2024 : additionne-les, divise par 2, puis rapporte à l’effectif moyen.","type":"nombre","unite":"%"},{"enonce":"Combien l’entreprise gagne-t-elle en 2024, une fois les 40 000 € investis retirés des économies d’heures d’absence ?","aide":"Heures d’absence évitées × 25 €, puis retire 40 000 €.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r4c2"]},"explication":"Pour 2024, il faut les **3 520 heures d’absence** : taux = heures d’absence ÷ heures théoriques × 100."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 %","explication":"6 400 ÷ 128 000 × 100 = **5 %** en 2023."},{"cle":{"type":"choix","ids":["a"]},"explication":"Absences et mouvements de personnel ont **baissé** : de bonnes conditions de travail réduisent absentéisme et rotation, donc leurs coûts."},{"cle":{"type":"nombre","valeur":7.5,"tolerance":0},"affichage":"7,5 %","explication":"((6 + 6) ÷ 2) ÷ 80 × 100 = 6 ÷ 80 × 100 = **7,5 %**, contre 16,25 % en 2023."},{"cle":{"type":"nombre","valeur":32000,"tolerance":0},"affichage":"32 000 €","explication":"6 400 − 3 520 = 2 880 heures évitées ; 2 880 × 25 = 72 000 € ; 72 000 − 40 000 = **32 000 €** de gain net."}]$ex$::jsonb),
  ('66e6b32a-ea0b-53d0-9b69-eb855b924207'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Des chiffres de caisse à la fournée du lendemain","competence":"lire-tableau","situation":"La boulangerie du Port enregistre chaque vente avec son logiciel de caisse. La gérante veut passer des chiffres bruts à une décision utile.","documents":[{"id":"caisse","type":"tableau","titre":"Extrait du fichier de caisse","source":"Chiffres imaginés pour l’exercice.","colonnes":["Date","Produit","Quantité vendue"],"lignes":[["12/03","Baguette",142],["13/03","Baguette",98],["14/03","Baguette",105],["14/03","Croissant",61]]}],"questions":[{"enonce":"Combien de baguettes la boulangerie a-t-elle vendues en tout du 12 au 14 mars ?","aide":"Additionne les trois lignes « Baguette ».","type":"nombre","unite":"baguettes"},{"enonce":"Associe chaque énoncé à son niveau : donnée, information ou connaissance.","aide":"La donnée est brute ; l’information a un contexte ; la connaissance permet d’agir.","type":"association","gauche":[{"id":"g0","texte":"« 142 »"},{"id":"g1","texte":"« 142 baguettes ont été vendues le 12/03 »"},{"id":"g2","texte":"« Quand la pluie est annoncée, on cuit moins de viennoiseries : moins d’invendus »"}],"droite":[{"id":"d0","texte":"Connaissance"},{"id":"d1","texte":"Donnée"},{"id":"d2","texte":"Information"}]},{"enonce":"Après chaque vente, le logiciel recalcule automatiquement le stock restant de baguettes. Quelle fonction du système d’information est à l’œuvre ?","aide":"Le logiciel fait un calcul sur des données déjà enregistrées.","type":"choix","options":[{"id":"a","texte":"Collecter"},{"id":"b","texte":"Mémoriser"},{"id":"c","texte":"Traiter"},{"id":"d","texte":"Diffuser"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":345,"tolerance":0},"affichage":"345 baguettes","explication":"142 + 98 + 105 = **345 baguettes** : en regroupant des données, on obtient une information."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"« 142 » seul est une **donnée**. Mise en contexte, c’est une **information**. Interprétée pour décider quoi cuire, c’est une **connaissance**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Calculer un stock à partir des ventes enregistrées, c’est **traiter** l’information. Collecter, mémoriser et diffuser sont d’autres fonctions."}]$ex$::jsonb),
  ('66e6b32a-ea0b-53d0-9b69-eb855b924207'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La salle de sport Énergym et ses fiches d’inscription","competence":"analyser-document","situation":"La salle Énergym fait remplir un formulaire à chaque nouvel adhérent. Lina, qui vient de quitter la salle, trouve qu’on lui a demandé trop de choses et qu’on garde ses données.","documents":[{"id":"form","type":"fiche","modele":"affiche","entete":"Formulaire d’inscription","sousTitre":"Énergym — finalité : gérer l’abonnement et prévenir en cas de fermeture","emoji":"🏋️","lignes":[{"texte":"Nom et prénom","id":"z1"},{"texte":"Adresse électronique","id":"z2"},{"texte":"Numéro de téléphone","id":"z3"},{"texte":"Numéro de sécurité sociale","id":"z4"},{"texte":"Revenus de la famille","id":"z5"}],"pied":"Formulaire écrit pour l’exercice ; salle imaginaire."}],"questions":[{"enonce":"Touche les deux informations dont la salle n’a pas besoin pour sa finalité.","aide":"Pour gérer un abonnement et prévenir en cas de fermeture, que faut-il vraiment connaître ?","type":"zone","document":"form","multiple":true},{"enonce":"Énergym conserve toutes les données de Lina cinq ans après son départ, « au cas où ». Quel principe du RGPD n’est pas respecté ?","aide":"Une donnée ne doit pas être gardée plus longtemps que la finalité ne le justifie.","type":"choix","options":[{"id":"a","texte":"Le droit à la portabilité des données"},{"id":"b","texte":"La finalité précise de la collecte"},{"id":"c","texte":"La sécurité des données stockées"},{"id":"d","texte":"La durée de conservation limitée"}],"multiple":false},{"enonce":"Associe chaque demande de Lina au droit qu’elle exerce.","aide":"Chaque droit correspond à une action précise : voir, supprimer, corriger, refuser.","type":"association","gauche":[{"id":"g0","texte":"Elle demande une copie des données que la salle détient sur elle"},{"id":"g1","texte":"Elle demande de supprimer sa fiche après son départ"},{"id":"g2","texte":"Elle fait corriger une adresse erronée"},{"id":"g3","texte":"Elle refuse de recevoir des publicités"}],"droite":[{"id":"d0","texte":"Droit de rectification"},{"id":"d1","texte":"Droit d’effacement"},{"id":"d2","texte":"Droit d’opposition"},{"id":"d3","texte":"Droit d’accès"}]},{"enonce":"Lina juge que la salle ne respecte pas ses droits. Quelle autorité peut contrôler et sanctionner en France ?","aide":"Elle contrôle le respect de la protection des données personnelles.","type":"choix","options":[{"id":"a","texte":"Le commissaire aux comptes"},{"id":"b","texte":"L’INSEE"},{"id":"c","texte":"La CNIL"},{"id":"d","texte":"La Cour des comptes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4","z5"]},"explication":"Le principe de **minimisation** impose de ne collecter que le nécessaire : ni sécurité sociale ni revenus ne servent à gérer un abonnement."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le RGPD impose une **durée de conservation limitée** : une fois l’abonnement terminé, il n’y a plus de raison de garder la fiche."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Accès, effacement, rectification et opposition sont des **droits** que le RGPD reconnaît aux personnes sur leurs données."},{"cle":{"type":"choix","ids":["c"]},"explication":"En France, la **CNIL** contrôle l’application du RGPD et peut prononcer des sanctions."}]$ex$::jsonb),
  ('66e6b32a-ea0b-53d0-9b69-eb855b924207'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Plage&Co : la canicule fait-elle vendre des parasols ?","competence":"analyser-document","situation":"Le site de vente en ligne Plage&Co vend des parasols. Son responsable croise ses ventes avec des relevés de température publiés en accès libre pour mieux anticiper les stocks.","documents":[{"id":"ventes","type":"graphique","forme":"barres","titre":"Parasols vendus par semaine","source":"Chiffres imaginés pour l’exercice ; site imaginaire.","categories":["S1","S2","S3","S4","S5","S6"],"series":[{"nom":"Parasols vendus","valeurs":[120,135,410,98,430,125],"teinte":"violet"}],"axeY":{"titre":"Parasols vendus","min":0,"max":500,"pas":100},"axeX":{"titre":"Semaine"},"valeurs":false},{"id":"meteo","type":"tableau","titre":"Température maximale de la semaine (relevés ouverts)","source":"Relevés imaginés pour l’exercice, présentés comme données ouvertes.","colonnes":["Semaine","S1","S2","S3","S4","S5","S6"],"lignes":[["Température max (°C)",18,19,31,17,33,20]],"enteteLignes":true}],"questions":[{"enonce":"Touche la barre de la semaine où la température maximale a été la plus élevée.","aide":"Repère la semaine la plus chaude dans le tableau, puis cherche-la sur le graphique.","type":"zone","document":"ventes","multiple":false},{"enonce":"En moyenne, combien de parasols sont vendus par semaine quand la température dépasse 30 °C ?","aide":"Repère les semaines au-dessus de 30 °C, puis fais la moyenne de leurs ventes.","type":"nombre","unite":"parasols"},{"enonce":"Et quand la température ne dépasse pas 30 °C, quelle est la moyenne hebdomadaire des ventes ?","aide":"Les quatre autres semaines : S1, S2, S4 et S6.","type":"nombre","unite":"parasols"},{"enonce":"Quelle connaissance le responsable peut-il en tirer pour décider de ses commandes ?","aide":"Compare les deux moyennes : 420 contre 119,5.","type":"choix","options":[{"id":"a","texte":"Les ventes ne dépendent pas de la météo, le stock actuel suffit toute l’année"},{"id":"b","texte":"Il faut vendre un parasol sur deux dès que la température dépasse 25 °C"},{"id":"c","texte":"Les parasols se vendent mieux quand il fait moins de 20 °C, il faut augmenter les stocks"},{"id":"d","texte":"Quand plus de 30 °C sont annoncés, il faut prévoir environ 3,5 fois plus de parasols en stock"}],"multiple":false},{"enonce":"Associe chaque exemple à la catégorie de données qu’il illustre.","aide":"Une donnée est personnelle quand elle se rapporte à une personne identifiable.","type":"association","gauche":[{"id":"g0","texte":"Les relevés de température publiés librement et réutilisables"},{"id":"g1","texte":"L’adresse électronique d’un client du site"},{"id":"g2","texte":"Des millions de clics enregistrés chaque jour sur le site"}],"droite":[{"id":"d0","texte":"Données ouvertes"},{"id":"d1","texte":"Mégadonnées"},{"id":"d2","texte":"Donnée personnelle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"La température a été la plus haute en **S5** (33 °C) : c’est là que le site a vendu 430 parasols."},{"cle":{"type":"nombre","valeur":420,"tolerance":0},"affichage":"420 parasols","explication":"S3 (31 °C) et S5 (33 °C) : (410 + 430) ÷ 2 = **420 parasols** par semaine."},{"cle":{"type":"nombre","valeur":119.5,"tolerance":0.05},"affichage":"119,5 parasols","explication":"(120 + 135 + 98 + 125) ÷ 4 = 478 ÷ 4 = **119,5 parasols** par semaine."},{"cle":{"type":"choix","ids":["d"]},"explication":"420 ÷ 119,5 ≈ 3,5 : en croisant ses données avec les données ouvertes, il obtient une **connaissance** qui permet d’agir."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Des relevés publics libres sont des **données ouvertes** ; un e-mail est une **donnée personnelle** ; un flux massif de clics relève des **mégadonnées**."}]$ex$::jsonb),
  ('79146d57-e806-5985-a4f2-71e2be47a9f8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les droits dans l’espace numérique du lycée","competence":"lire-tableau","situation":"Au lycée imaginaire Jean-Macé, chaque élève et chaque professeur a un rôle dans l’espace numérique de travail. Léo, élève délégué, veut savoir ce qu’il peut faire dans le dossier de la classe.","documents":[{"id":"droits","type":"tableau","titre":"Droits selon le rôle","source":"Droits simplifiés, espace imaginaire.","colonnes":["Rôle","Lire","Modifier","Supprimer"],"lignes":[["Administrateur","Oui","Oui","Oui"],["Contributeur","Oui","Oui","Non"],["Lecteur","Oui","Non","Non"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le rôle qui permet seulement de consulter les documents.","aide":"Cherche la ligne où il n’y a qu’un seul « Oui ».","type":"zone","document":"droits","multiple":false},{"enonce":"Léo, contributeur, veut supprimer un fichier de la classe. Que se passe-t-il ?","aide":"Lis la colonne « Supprimer » à la ligne du contributeur.","type":"choix","options":[{"id":"a","texte":"Il ne peut pas : seul l’administrateur peut supprimer"},{"id":"b","texte":"Il peut le faire, mais seulement la nuit"},{"id":"c","texte":"Il peut le faire, car un contributeur peut tout faire"},{"id":"d","texte":"Il ne peut pas lire le fichier, donc pas le supprimer"}],"multiple":false},{"enonce":"Complète les responsabilités de l’utilisateur.","aide":"Deux responsabilités citées dans le cours : un accès personnel et le caractère privé des fichiers.","type":"trous","segments":["Chaque utilisateur doit protéger son ",0," et respecter la ",1," des documents."],"banque":["confidentialité","adresse","mot de passe","vitesse"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le **lecteur** peut lire mais ni modifier ni supprimer."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le contributeur peut lire et modifier, mais pas supprimer. Gérer finement les droits évite les **suppressions accidentelles**."},{"cle":{"type":"trous","trous":[["mot de passe"],["confidentialite"]]},"affichage":"mot de passe · confidentialité","explication":"Protéger son **mot de passe** et respecter la **confidentialité** font partie des responsabilités de l’utilisateur."}]$ex$::jsonb),
  ('79146d57-e806-5985-a4f2-71e2be47a9f8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un agent conversationnel pour le service client","competence":"analyser-document","situation":"Le service client d’un site de vente en ligne reçoit 500 demandes par jour. La direction teste un agent conversationnel pour les demandes simples, en gardant des conseillers pour le reste.","documents":[{"id":"demandes","type":"graphique","forme":"barres-h","titre":"Demandes reçues par jour","source":"Chiffres imaginés pour l’exercice ; site imaginaire.","categories":["Suivre un colis","Demander les horaires","Retourner un produit","Litige complexe"],"series":[{"nom":"Demandes","valeurs":[200,100,120,80],"teinte":"turquoise"}],"axeY":{"titre":"Demandes par jour","min":0,"max":250,"pas":50},"valeurs":false},{"id":"mail","type":"texte","genre":"lettre","titre":"Courriel d’un conseiller","source":"Courriel écrit pour l’exercice.","blocs":["Hier, l’agent conversationnel a répondu à une cliente qu’elle avait 60 jours pour renvoyer son achat. La règle est de 14 jours. Il a inventé la réponse avec aplomb, et nous avons dû rattraper l’erreur."]}],"questions":[{"enonce":"Touche le type de demande le plus fréquent.","aide":"Cherche la barre la plus longue.","type":"zone","document":"demandes","multiple":false},{"enonce":"L’agent traite le suivi de colis et les horaires. Quelle part des 500 demandes quotidiennes cela représente-t-il, en pourcentage ?","aide":"Additionne les deux barres concernées, puis divise par 500.","type":"nombre","unite":"%"},{"enonce":"Qui doit traiter chaque demande dans la nouvelle organisation ?","aide":"Les tâches simples et répétitives s’automatisent ; le jugement reste humain.","type":"categories","categories":[{"id":"c0","texte":"Agent conversationnel"},{"id":"c1","texte":"Conseiller humain"}],"items":[{"id":"i0","texte":"Donner l’heure de fermeture du service client"},{"id":"i1","texte":"Indiquer où en est un colis"},{"id":"i2","texte":"Résoudre un litige complexe avec un client en colère"},{"id":"i3","texte":"Décider d’un geste commercial pour un cas particulier"}]},{"enonce":"Quel risque de l’intelligence artificielle le courriel du conseiller illustre-t-il ?","aide":"Relis ce que dit l’agent sur le délai de retour.","type":"choix","options":[{"id":"a","texte":"Des erreurs et des réponses inventées qu’il faut contrôler"},{"id":"b","texte":"Une perte de données due à un mot de passe volé"},{"id":"c","texte":"La suppression de tous les emplois du service client"},{"id":"d","texte":"Une dépendance totale à un unique fournisseur d’énergie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"**Suivre un colis** : 200 demandes par jour, soit 40 % du total."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"200 + 100 = 300 demandes ; 300 ÷ 500 = **60 %** des demandes peuvent être automatisées."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"L’IA automatise les tâches **répétitives** ; les cas complexes demandent du **jugement** et de la relation humaine."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’IA peut commettre des **erreurs** et inventer des réponses : les conseillers doivent contrôler et alimenter une base de connaissances."}]$ex$::jsonb),
  ('79146d57-e806-5985-a4f2-71e2be47a9f8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quatre équipes, une fête du lycée","competence":"analyser-document","situation":"Pour la fête du lycée, quatre équipes d’élèves ont préparé leurs idées avec le même budget et le même temps. Le comité n’en a pas retenu autant dans chacune. Pourquoi ?","documents":[{"id":"equipes","type":"tableau","titre":"Les quatre équipes","source":"Situation imaginée pour l’exercice.","colonnes":["Équipe","Objectif partagé ?","Règles et confiance","Outil","Idées retenues"],"lignes":[["Décors","Oui","Rôles et règles écrits","Document co-édité, droits par rôle",14],["Musique","Non : chacun veut sa playlist","Aucune règle","Messagerie",3],["Buvette","Oui","Rôles et règles écrits","Wiki partagé",12],["Communication","Oui","Chacun peut tout modifier","Dossier partagé sans droits",5]],"enteteLignes":true},{"id":"com","type":"texte","genre":"recit","titre":"Le journal de l’équipe Communication","source":"Texte écrit pour l’exercice.","blocs":["Dans le dossier de l’équipe, les huit élèves ont le même droit : tout modifier et tout supprimer. Mardi, Sacha a supprimé par erreur le plan de la fête. Personne ne savait qui avait la dernière version."]}],"questions":[{"enonce":"Touche la case qui montre qu’une des conditions de l’intelligence collective manque à l’équipe Musique.","aide":"L’une des conditions est un objectif commun à tous.","type":"zone","document":"equipes","multiple":false},{"enonce":"Quelle part des idées retenues vient des équipes Décors et Buvette, en pourcentage arrondi à l’unité ?","aide":"Additionne les idées des quatre équipes, puis celles de Décors et de Buvette.","type":"nombre","unite":"%"},{"enonce":"Quel risque une gestion plus fine des droits aurait-elle évité à l’équipe Communication ?","aide":"Relis ce qui est arrivé à Sacha mardi.","type":"choix","options":[{"id":"a","texte":"Une panne de messagerie pendant la fête"},{"id":"b","texte":"Une suppression accidentelle d’un fichier important"},{"id":"c","texte":"Le départ d’un élève vers une autre équipe"},{"id":"d","texte":"Une fuite de données personnelles vers la CNIL"}],"multiple":false},{"enonce":"Quelle organisation de l’espace partagé aiderait le mieux l’équipe Communication ?","aide":"Pense à ce que fait l’équipe Décors : rôles, droits et règles.","type":"choix","options":[{"id":"a","texte":"Un dossier privé par élève, sans partage entre les membres"},{"id":"b","texte":"Un seul compte partagé dont tout le monde connaît le mot de passe"},{"id":"c","texte":"Une messagerie instantanée sans aucun dossier commun"},{"id":"d","texte":"Un administrateur, des contributeurs et des lecteurs, avec des règles écrites"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Dans l’équipe Musique, l’**objectif n’est pas partagé** : chacun poursuit sa propre playlist, la mise en commun échoue."},{"cle":{"type":"nombre","valeur":76,"tolerance":0.5},"affichage":"76 %","explication":"Total : 14 + 3 + 12 + 5 = 34 ; Décors et Buvette : 26. 26 ÷ 34 ≈ 0,7647, soit **76 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Quand tout le monde peut tout supprimer, une **suppression accidentelle** est possible : les droits doivent dépendre du rôle."},{"cle":{"type":"choix","ids":["d"]},"explication":"Des **rôles**, des **droits** et des règles claires (comme dans l’équipe Décors) sécurisent le partage et rendent la coopération efficace."}]$ex$::jsonb),
  ('6672653f-dff4-57cd-a85e-394af3898942'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Du clic du client au colis expédié","competence":"observer-schema","situation":"Sur le site de vente en ligne du magasin Sport’Nord, chaque commande suit le même parcours. Salomé, stagiaire, doit comprendre ce processus de bout en bout.","documents":[{"id":"process","type":"chaine","disposition":"colonne","titre":"Le processus de vente en ligne","source":"Schéma simplifié ; magasin imaginaire.","noeuds":[{"id":"z1","texte":"Commande du client","emoji":"🛒"},{"id":"z2","texte":"Vérification du paiement","emoji":"💳"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Expédition","emoji":"🚚"},{"id":"z5","texte":"Facturation","emoji":"🧾"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche l’étape qui joue le rôle d’événement déclencheur du processus.","aide":"L’événement déclencheur est ce qui met tout le processus en route.","type":"zone","document":"process","multiple":false},{"enonce":"Quelle activité manque à la place du point d’interrogation, entre le paiement et l’expédition ?","aide":"Avant d’expédier, il faut avoir constitué le colis.","type":"choix","options":[{"id":"a","texte":"La préparation du colis"},{"id":"b","texte":"La clôture des comptes"},{"id":"c","texte":"Le suivi et l’avis client"},{"id":"d","texte":"La paie des salariés"}],"multiple":false},{"enonce":"Associe chaque notion à son exemple dans ce processus.","aide":"Un processus part d’un événement, suit des activités et aboutit à un résultat pour un client.","type":"association","gauche":[{"id":"g0","texte":"Événement déclencheur"},{"id":"g1","texte":"Résultat attendu"},{"id":"g2","texte":"Décision"}],"droite":[{"id":"d0","texte":"Paiement accepté ? oui ou non"},{"id":"d1","texte":"Le client reçoit son colis"},{"id":"d2","texte":"Le client valide son panier"}]}]}$ex$::jsonb,
