 pour l’exercice.","colonnes":["Solution","Coût"],"lignes":[["Serveur acheté","12 000 € amortis sur 5 ans, plus 1 500 € de maintenance par an"],["Cloud","40 € par utilisateur et par mois"],["Nombre d’utilisateurs aujourd’hui","8"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’élément du schéma qui représente une décision.","aide":"Cherche la forme qui pose une question avec deux réponses possibles.","type":"zone","document":"flux","multiple":false},{"enonce":"Que se passe-t-il d’après le schéma quand le paiement n’est pas accepté ?","aide":"Suis la flèche « non » qui part du losange.","type":"choix","options":[{"id":"a","texte":"Le client reçoit un message d’erreur"},{"id":"b","texte":"Le colis est envoyé à l’entrepôt"},{"id":"c","texte":"La commande est préparée puis expédiée"},{"id":"d","texte":"La commande est enregistrée sans paiement"}],"multiple":false},{"enonce":"Quel est le coût annuel du serveur acheté, en euros ?","aide":"Amortissement annuel : 12 000 ÷ 5, puis ajoute la maintenance.","type":"nombre","unite":"€"},{"enonce":"Quel est le coût annuel du cloud pour les 8 utilisateurs, en euros ?","aide":"Utilisateurs × prix mensuel × 12 mois.","type":"nombre","unite":"€"},{"enonce":"À partir de combien d’utilisateurs le cloud devient-il plus cher que le serveur acheté ?","aide":"Un utilisateur coûte 40 × 12 = 480 € par an : compare à 3 900 €.","type":"choix","options":[{"id":"a","texte":"9 utilisateurs"},{"id":"b","texte":"10 utilisateurs"},{"id":"c","texte":"12 utilisateurs"},{"id":"d","texte":"8 utilisateurs"}],"multiple":false}]}$ex$::jsonb,
