  ('240fb557-5e5a-5c1b-8947-ab3d322ba126'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Yanis cherche sa problématique","competence":"argumenter","situation":"Yanis prépare son étude de gestion sur la librairie Page 12, où il fait son stage. Il hésite entre quatre formulations de problématique.","documents":[{"id":"idees","type":"tableau","titre":"Les quatre idées de Yanis","source":"Formulations écrites pour l’exercice ; librairie imaginaire.","colonnes":["N°","Formulation"],"lignes":[["1","L’informatique dans les entreprises"],["2","La librairie Page 12 a-t-elle un site marchand ?"],["3","En quoi le site marchand de la librairie Page 12 a-t-il rendu son organisation plus agile ?"],["4","Les organisations et le numérique"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la formulation qui est une bonne problématique : une question ouverte, précise et reliée au programme.","aide":"Cherche celle qui nomme l’organisation, un outil précis et une notion du programme.","type":"zone","document":"idees","multiple":false},{"enonce":"Classe chaque formulation : trop vague, trop fermée ou bonne problématique ?","aide":"Une question à laquelle on répond par oui ou non est fermée ; un simple thème ne pose aucune question.","type":"categories","categories":[{"id":"c0","texte":"Trop vague"},{"id":"c1","texte":"Trop fermée"},{"id":"c2","texte":"Bonne problématique"}],"items":[{"id":"i0","texte":"En quoi le site marchand de Page 12 l’a-t-il rendue plus agile ?"},{"id":"i1","texte":"La librairie Page 12 a-t-elle un site marchand ?"},{"id":"i2","texte":"L’informatique dans les entreprises"},{"id":"i3","texte":"Les organisations et le numérique"}]},{"enonce":"À quel chapitre du programme se rattache la problématique retenue ?","aide":"Repère la notion du programme dans la formulation : agile.","type":"choix","options":[{"id":"a","texte":"Le numérique : agilité ou rigidité ?"},{"id":"b","texte":"Mesurer la création de valeur"},{"id":"c","texte":"Ressources humaines et coût du travail"},{"id":"d","texte":"Le temps dans la gestion"}],"multiple":false}]}$ex$::jsonb,
