   $ex${"titre":"Le carnet de bord de Camille sur l’association Les Aiglons","competence":"analyser-document","situation":"Camille prépare son étude de gestion sur l’association sportive Les Aiglons. Son carnet de bord montre les sources qu’elle a consultées. Une information semble bizarre.","documents":[{"id":"carnet","type":"tableau","titre":"Extrait du carnet de bord","source":"Carnet imaginé pour l’exercice ; association imaginaire.","colonnes":["Date","Source","Information relevée"],"lignes":[["12/10","Site de l’association","180 licenciés"],["03/11","Entretien avec la trésorière","Cotisation moyenne : 95 €"],["17/11","Article de la presse locale","Environ 210 licenciés"],["24/11","Rapport annuel de l’association","182 licenciés"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque source : interne à l’organisation ou externe ?","aide":"Une source interne vient de l’organisation elle-même ou de ses membres.","type":"categories","categories":[{"id":"c0","texte":"Source interne"},{"id":"c1","texte":"Source externe"}],"items":[{"id":"i0","texte":"Rapport annuel de l’association"},{"id":"i1","texte":"Article de la presse locale"},{"id":"i2","texte":"Site de l’association"},{"id":"i3","texte":"Entretien avec la trésorière"}]},{"enonce":"Touche l’information qui s’écarte des autres sources sur le nombre de licenciés.","aide":"Trois sources donnent des chiffres voisins, une seule s’en éloigne.","type":"zone","document":"carnet","multiple":false},{"enonce":"Quel est l’écart entre le chiffre de la presse et celui du rapport annuel ?","aide":"Soustrais le chiffre du rapport à celui de l’article.","type":"nombre","unite":"licenciés"},{"enonce":"Que doit faire Camille face à cet écart avant de retenir un chiffre ?","aide":"Pour chaque source : qui parle ? quand ? dans quel but ?","type":"choix","options":[{"id":"a","texte":"Comparer qui parle, quand et dans quel but, puis croiser les sources"},{"id":"b","texte":"Supprimer les autres sources pour ne garder que la presse"},{"id":"c","texte":"Calculer la moyenne des quatre sources sans les vérifier"},{"id":"d","texte":"Retenir le chiffre de la presse, car il est le plus élevé"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes de l’étude de gestion.","aide":"On commence par le thème, on finit par l’oral ; l’analyse suit la collecte.","type":"ordre","items":[{"id":"a","texte":"Choisir l’organisation"},{"id":"b","texte":"Choisir un thème rattaché à une question de gestion"},{"id":"c","texte":"Préparer la soutenance orale"},{"id":"d","texte":"Analyser avec les notions du cours"},{"id":"e","texte":"Formuler une problématique"},{"id":"f","texte":"Collecter les informations"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Site, entretien avec un responsable et rapport annuel sont **internes** ; un article de presse est **externe**."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"L’article de presse annonce **environ 210 licenciés**, alors que le site et le rapport donnent 180 et 182."},{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28 licenciés","explication":"210 − 182 = **28 licenciés** d’écart : trop pour l’ignorer."},{"cle":{"type":"choix","ids":["a"]},"explication":"Croiser au moins deux sources et **vérifier leur origine** permet d’évaluer leur fiabilité (le chiffre de la presse est approximatif et peut être plus ancien ou plus large)."},{"cle":{"type":"ordre","ids":["b","a","e","f","d","c"]},"explication":"Thème → organisation → problématique → collecte → analyse → soutenance : c’est la **démarche** de l’étude de gestion."}]$ex$::jsonb),
  ('240fb557-5e5a-5c1b-8947-ab3d322ba126'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Lucie répète sa soutenance sur Sport’Nord","competence":"analyser-document","situation":"Lucie présente son étude de gestion sur le magasin Sport’Nord. Elle a chronométré sa répétition et se demande ce qu’il faut couper, et ce que le jury attend vraiment.","documents":[{"id":"plan","type":"texte","genre":"article","titre":"Le plan de Lucie","source":"Plan écrit pour l’exercice ; magasin imaginaire.","blocs":["Problématique : en quoi l’application de gestion des stocks a-t-elle rendu le magasin Sport’Nord plus agile ?","Partie 1 : une information qui circule plus vite entre la caisse et la réserve.","Partie 2 : mais des procédures plus rigides pour les vendeurs.","Partie 3 : des recommandations de paramétrage."]},{"id":"chrono","type":"tableau","titre":"Chronométrage de la répétition","source":"Chiffres imaginés pour l’exercice.","colonnes":["Temps de l’exposé","Durée (minutes)"],"lignes":[["Introduction",3],["Partie 1",3],["Partie 2",4],["Partie 3",2],["Conclusion",1]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot de la problématique qui renvoie à une notion du programme de sciences de gestion et numérique.","aide":"Quelle qualité de l’organisation est mise en question par l’application ?","type":"zone","document":"plan","multiple":false},{"enonce":"L’exposé doit durer dix minutes au plus. De combien de minutes la répétition de Lucie dépasse-t-elle cette limite ?","aide":"Additionne toutes les durées du tableau, puis compare à 10.","type":"nombre","unite":"minutes"},{"enonce":"Associe chaque temps de la soutenance à son contenu.","aide":"L’exposé a trois temps ; l’entretien avec le jury vient après.","type":"association","gauche":[{"id":"g0","texte":"Introduction"},{"id":"g1","texte":"Développement"},{"id":"g2","texte":"Conclusion"},{"id":"g3","texte":"Entretien"}],"droite":[{"id":"d0","texte":"La réponse à la problématique, une limite, une ouverture"},{"id":"d1","texte":"Justifier ses choix, définir les notions, raconter sa démarche"},{"id":"d2","texte":"L’organisation en quelques chiffres, la question de gestion, la problématique"},{"id":"d3","texte":"Deux ou trois parties : observations analysées avec les notions"}]},{"enonce":"Range chaque pratique : à faire ou à éviter pendant la soutenance ?","aide":"Le jury veut voir que tu raisonnes avec les notions et que tu expliques ta démarche.","type":"categories","categories":[{"id":"c0","texte":"À faire"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Répondre à la problématique en conclusion"},{"id":"i1","texte":"Expliquer sa démarche et citer ses sources"},{"id":"i2","texte":"Projeter un diaporama surchargé de texte"},{"id":"i3","texte":"Signaler une limite de son étude"},{"id":"i4","texte":"Décrire l’organisation sans jamais l’analyser"},{"id":"i5","texte":"Lire ses notes à voix haute"}]},{"enonce":"Hugo, un camarade, a fait rédiger sa conclusion par une IA sans le dire. Que penser de cette pratique ?","aide":"Le carnet de bord doit prouver que l’étude est la tienne.","type":"choix","options":[{"id":"a","texte":"Elle est recommandée, car l’IA ne commet jamais d’erreur"},{"id":"b","texte":"Elle est acceptable, car la conclusion est la partie la moins importante"},{"id":"c","texte":"Elle est acceptable à condition de ne pas citer ses sources ailleurs"},{"id":"d","texte":"Elle n’est pas acceptable : il faut dire d’où vient le texte, l’étude doit être la sienne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"L’**agilité** est la notion du programme (le numérique rend-il l’organisation agile ou rigide ?) : elle relie l’étude au cours."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 minutes","explication":"3 + 3 + 4 + 2 + 1 = 13 minutes ; 13 − 10 = **3 minutes** de trop."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"L’**introduction** pose le cadre, le **développement** analyse, la **conclusion** répond et ouvre, l’**entretien** vérifie ta démarche."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Une bonne soutenance **répond**, assume ses limites et explique sa démarche ; lire ses notes, surcharger un diaporama ou rester descriptif sont des erreurs."},{"cle":{"type":"choix","ids":["d"]},"explication":"Faire rédiger par une IA **sans le dire** n’est pas acceptable ; cite tes sources et explique ta démarche. L’IA peut aussi se tromper."}]$ex$::jsonb),
  ('d7a6707f-cb7c-53a2-936b-03e067b76c98'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre personnes, quatre façons de se dire en bonne santé","competence":"analyser-document","situation":"Au lycée, Inès recueille quatre témoignages sur ce que « être en bonne santé » veut dire. Avant de les classer, elle les lit avec attention.","documents":[{"id":"voix","type":"tableau","titre":"Quatre témoignages","source":"Texte écrit pour l’exercice.","colonnes":["Personne","Ce qu’elle dit"],"lignes":[["Mathis, 17 ans","Mon bilan chez le médecin du sport est normal : aucune lésion, aucun symptôme. Je suis donc en bonne santé."],["Odette, 78 ans","Je suis diabétique et mon traitement est bien équilibré. Je me sens bien, c’est tout ce qui compte pour moi."],["Hugo, 45 ans","Depuis mon accident, je marche avec une canne, mais je travaille, je conduis, je fais mes courses : je m’adapte."],["Nadia, 40 ans","Je ne suis pas malade, mais je suis épuisée et je vois peu de monde : je ne me sens pas bien dans ma vie."]],"enteteLignes":true}],"questions":[{"enonce":"Touche le témoignage de la personne qui juge sa santé uniquement par l’absence de maladie ou de lésion.","aide":"Cherche celui qui s’appuie sur un examen médical.","type":"zone","document":"voix","multiple":false},{"enonce":"Associe chaque personne à l’approche de la santé qu’elle illustre.","aide":"Demande-toi si la personne parle d’examen, de ressenti ou d’activités qu’elle accomplit.","type":"association","gauche":[{"id":"g0","texte":"Mathis"},{"id":"g1","texte":"Odette"},{"id":"g2","texte":"Hugo"}],"droite":[{"id":"d0","texte":"Approche subjective"},{"id":"d1","texte":"Approche biomédicale"},{"id":"d2","texte":"Approche fonctionnelle"}]},{"enonce":"Selon la définition de l’OMS de 1946, Nadia est-elle en bonne santé ?","aide":"L’OMS parle d’un bien-être physique, mental ET social.","type":"choix","options":[{"id":"a","texte":"Non : le complet bien-être mental et social lui manque"},{"id":"b","texte":"Oui : elle n’a aucune maladie ni aucune lésion"},{"id":"c","texte":"Impossible à dire sans un examen médical complet"},{"id":"d","texte":"Oui : elle accomplit ses activités sans difficulté"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"C’est **Mathis** : il se fie au bilan médical (aucune lésion, aucun symptôme). C’est l’**approche biomédicale**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Mathis** : biomédicale (absence de lésion). **Odette** : subjective (elle se sent bien malgré sa maladie). **Hugo** : fonctionnelle (il accomplit ses activités et s’adapte)."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’OMS définit la santé comme un **état de complet bien-être physique, mental et social**, pas seulement l’absence de maladie. Nadia est épuisée et isolée : il lui manque une part de ce bien-être."}]$ex$::jsonb),
  ('d7a6707f-cb7c-53a2-936b-03e067b76c98'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce qui inquiète les habitants de Val-Clair","competence":"lire-graphique","situation":"Le CCAS de Val-Clair, ville imaginaire, a demandé à 400 habitants quel problème de santé les inquiète le plus. Il veut s’en servir pour proposer des actions à la mairie.","documents":[{"id":"enq","type":"graphique","forme":"barres-h","titre":"Problème de santé jugé le plus inquiétant","source":"Chiffres imaginés pour l’exercice.","categories":["Maladies chroniques","Santé mentale","Manque de médecins","Tabac et alcool","Isolement des aînés"],"series":[{"nom":"Habitants","valeurs":[120,100,80,60,40],"teinte":"violet"}],"axeY":{"titre":"Habitants (sur 400)","min":0,"max":140,"pas":20},"axeX":{"titre":"Problème cité"}}],"questions":[{"enonce":"Touche le problème de santé cité par le plus d’habitants.","aide":"Cherche la barre la plus longue.","type":"zone","document":"enq","multiple":false},{"enonce":"Quelle part des 400 habitants cite la santé mentale ?","aide":"Divise l’effectif lu par 400, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Les maladies chroniques et la santé mentale réunies : quelle part des habitants cela représente-t-il ?","aide":"Additionne d’abord les deux effectifs.","type":"nombre","unite":"%"},{"enonce":"Classe chaque situation : santé individuelle ou santé collective.","aide":"La santé collective concerne un groupe, mesuré par des indicateurs.","type":"categories","categories":[{"id":"c0","texte":"Santé individuelle"},{"id":"c1","texte":"Santé collective"}],"items":[{"id":"i0","texte":"La mairie mesure la part d’habitants diabétiques"},{"id":"i1","texte":"Une enquête relève l’état de santé des 400 habitants"},{"id":"i2","texte":"Mme Roux consulte son médecin pour une toux"},{"id":"i3","texte":"Karim se fait soigner une carie"},{"id":"i4","texte":"La ville publie son taux de mortalité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Les **maladies chroniques** (diabète, cancers, maladies cardio-vasculaires…) arrivent en tête avec 120 habitants."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"100 ÷ 400 × 100 = **25 %** des habitants citent la santé mentale."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 %","explication":"(120 + 100) ÷ 400 × 100 = **55 %** : plus d’un habitant sur deux."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"La **santé individuelle** est celle d’une personne et des soignants. La **santé collective** décrit l’état d’un groupe, mesuré par des indicateurs, et relève des pouvoirs publics."}]$ex$::jsonb),
  ('d7a6707f-cb7c-53a2-936b-03e067b76c98'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La santé, un idéal ou une ressource ?","competence":"argumenter","situation":"Lina et Yanis s’envoient des SMS la veille du contrôle : le grand-père de Yanis est diabétique, et ils se demandent s’il est « en bonne santé ». Une frise les aide à situer les définitions du cours.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de la veille du contrôle","source":"Texte écrit pour l’exercice.","participants":[{"nom":"Yanis","emoji":"👦","cote":"droite"},{"nom":"Lina","emoji":"👧","cote":"gauche"}],"repliques":[{"qui":"Yanis","texte":"Mon grand-père a un diabète bien équilibré et il dit qu’il est en pleine forme. Mais il a une maladie, non ?"},{"qui":"Lina","texte":"Pour l’approche biomédicale, il n’est pas en bonne santé. Pour l’approche subjective, si !"},{"qui":"Yanis","texte":"Et l’OMS ? Un état de complet bien-être, ça n’arrive presque jamais."},{"qui":"Lina","texte":"C’est la critique qu’on lui fait : c’est un idéal difficile à atteindre. La charte d’Ottawa y voit plutôt une ressource du quotidien."},{"qui":"Yanis","texte":"Donc la santé, ça dépend de la culture, de l’époque, de l’âge…"}]},{"id":"frise","type":"frise","titre":"Trois définitions repères","debut":1900,"fin":2000,"pas":20,"evenements":[{"id":"z1","date":1920,"nom":"Winslow"},{"id":"z2","date":1946,"nom":"Constitution de l’OMS"},{"id":"z3","date":1986,"nom":"Charte d’Ottawa"}]}],"questions":[{"enonce":"Selon l’approche biomédicale, le grand-père de Yanis est-il en bonne santé ?","aide":"L’approche biomédicale juge d’après la présence ou non d’une maladie.","type":"choix","options":[{"id":"a","texte":"On ne peut pas répondre sans l’avis de l’OMS"},{"id":"b","texte":"Non : il est atteint d’une maladie"},{"id":"c","texte":"Oui : son traitement le rend invulnérable"},{"id":"d","texte":"Oui : il se sent en pleine forme"}],"multiple":false},{"enonce":"Touche le mot qui résume la critique faite à la définition de l’OMS.","aide":"Lina le dit dans son dernier long message.","type":"zone","document":"sms","multiple":false},{"enonce":"Associe chaque idée du dialogue à la notion du cours qu’elle illustre.","aide":"Relis chaque réplique de Lina et de Yanis.","type":"association","gauche":[{"id":"g0","texte":"Il se sent en pleine forme malgré sa maladie"},{"id":"g1","texte":"Un état de complet bien-être, ça n’arrive presque jamais"},{"id":"g2","texte":"Une ressource du quotidien"},{"id":"g3","texte":"Ça dépend de la culture et de l’époque"}],"droite":[{"id":"d0","texte":"Charte d’Ottawa"},{"id":"d1","texte":"Critique de la définition de l’OMS"},{"id":"d2","texte":"Relativité de la santé"},{"id":"d3","texte":"Approche subjective"}]},{"enonce":"Touche l’événement de la frise où la santé est présentée comme une ressource de la vie quotidienne.","aide":"Le dialogue en parle après avoir critiqué l’OMS.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Constitution de l’OMS de la charte d’Ottawa ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"L’approche **biomédicale** définit la santé comme l’absence de maladie, de lésion ou de symptôme : le diabète est une maladie, donc elle ne le juge pas en bonne santé. C’est l’approche **subjective** qui retient son ressenti."},{"cle":{"type":"zone","ids":["m62"]},"explication":"On reproche à l’OMS de décrire un **idéal** : un complet bien-être physique, mental et social est presque impossible à atteindre."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Le ressenti, c’est l’approche **subjective** ; l’idéal inatteignable, la **critique de l’OMS** ; la santé comme ressource, la **charte d’Ottawa** ; la dépendance à la culture et à l’époque, la **relativité** de la santé."},{"cle":{"type":"zone","ids":["z3"]},"explication":"La **charte d’Ottawa**, en 1986, voit la santé comme une ressource de la vie quotidienne."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 ans","explication":"1986 − 1946 = **40 ans**."}]$ex$::jsonb),
  ('0302f027-12d6-50ec-a753-3cf3099a3080'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les apprentissages d’Adèle, de 6 à 30 ans","competence":"analyser-document","situation":"Adèle a grandi à Val-Clair, ville imaginaire. Au fil des années, elle a appris à vivre avec les autres dans des endroits très différents.","documents":[{"id":"adele","type":"tableau","titre":"Où Adèle apprend à vivre en société","source":"Chiffres imaginés pour l’exercice.","colonnes":["Âge","Où elle apprend","Ce qu’elle apprend"],"lignes":[["6 ans","Sa famille","À dire merci et à partager"],["9 ans","L’école","À attendre son tour pour parler"],["14 ans","Ses amis du collège","Les expressions et les modes de son groupe"],["19 ans","Son premier emploi d’été","À être ponctuelle et à travailler en équipe"],["30 ans","Une association de quartier","À s’engager pour des causes communes"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’instance de socialisation primaire la plus importante dans l’enfance.","aide":"C’est la première des instances qu’Adèle rencontre.","type":"zone","document":"adele","multiple":false},{"enonce":"Classe chaque lieu d’apprentissage d’Adèle : socialisation primaire ou secondaire.","aide":"La socialisation primaire a lieu pendant l’enfance.","type":"categories","categories":[{"id":"c0","texte":"Primaire (enfance)"},{"id":"c1","texte":"Secondaire (toute la vie)"}],"items":[{"id":"i0","texte":"L’école"},{"id":"i1","texte":"Ses amis du collège"},{"id":"i2","texte":"Une association de quartier"},{"id":"i3","texte":"Son premier emploi d’été"},{"id":"i4","texte":"Sa famille"}]},{"enonce":"Que montre la dernière ligne du tableau ?","aide":"Adèle a 30 ans dans cette ligne.","type":"choix","options":[{"id":"a","texte":"La socialisation continue tout au long de la vie"},{"id":"b","texte":"La socialisation s’arrête à la fin de l’enfance"},{"id":"c","texte":"La socialisation est réservée aux adultes salariés"},{"id":"d","texte":"La socialisation ne passe que par la famille"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La **famille** est la principale instance de socialisation primaire : c’est elle qui transmet les premières normes et valeurs."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"La socialisation **primaire** passe par la famille, l’école et les pairs. La **secondaire** se poursuit tout au long de la vie : travail, associations, médias."},{"cle":{"type":"choix","ids":["a"]},"explication":"À 30 ans, Adèle apprend encore : la socialisation **n’est jamais terminée**, elle se poursuit par la socialisation secondaire."}]$ex$::jsonb),
  ('0302f027-12d6-50ec-a753-3cf3099a3080'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La charte du club de basket","competence":"analyser-document","situation":"Le club de basket de Val-Clair, imaginaire, affiche sa charte à l’entrée du gymnase. Ses règles disent beaucoup de ce que le groupe attend de ses membres.","documents":[{"id":"charte","type":"fiche","modele":"affiche","entete":"Charte du club","sousTitre":"Basket Val-Clair","emoji":"🏀","source":"Texte écrit pour l’exercice.","lignes":[{"texte":"La solidarité entre joueurs","id":"z1","gras":true},{"texte":"Le respect de chacun","id":"z2","gras":true},{"separateur":true},{"texte":"Serrer la main de l’adversaire après le match","id":"z3"},{"texte":"Arriver dix minutes avant l’entraînement","id":"z4"},{"texte":"Aider les plus jeunes à s’échauffer","id":"z5"},{"texte":"Pas d’alcool lors des troisièmes mi-temps","id":"z6"}],"pied":"Ensemble, on joue mieux."}],"questions":[{"enonce":"Touche les deux lignes en gras : ce sont les idéaux auxquels le club adhère.","aide":"Un idéal commun à tout le groupe est une valeur.","type":"zone","document":"charte","multiple":true},{"enonce":"Touche la règle qui influence directement les habitudes de santé des joueurs.","aide":"Pense à l’alcool.","type":"zone","document":"charte","multiple":false},{"enonce":"Associe chaque norme à la valeur dont elle découle.","aide":"Une norme est la règle de conduite qui traduit une valeur.","type":"association","gauche":[{"id":"g0","texte":"Serrer la main de l’adversaire"},{"id":"g1","texte":"Aider les plus jeunes à s’échauffer"}],"droite":[{"id":"d0","texte":"La solidarité entre joueurs"},{"id":"d1","texte":"Le respect de chacun"}]},{"enonce":"Complète avec le bon mot.","aide":"Un idéal, c’est une valeur ; une règle de conduite, c’est une norme.","type":"trous","segments":["Dans la charte, « la solidarité » est une ",0," ; « arriver dix minutes avant l’entraînement » est une ",1,"."],"banque":["valeur","fait social","instance","norme"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"La **solidarité** et le **respect** sont des **valeurs** : des idéaux auxquels le groupe adhère. Les autres lignes sont des normes."},{"cle":{"type":"zone","ids":["z6"]},"explication":"Interdire l’alcool aux troisièmes mi-temps est une **norme** qui agit sur les habitudes de vie : les conduites de santé s’apprennent dans les groupes."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"Une **norme** découle d’une **valeur** : serrer la main exprime le respect, aider les plus jeunes exprime la solidarité."},{"cle":{"type":"trous","trous":[["valeur"],["norme"]]},"affichage":"valeur · norme","explication":"La **valeur** est un idéal auquel un groupe adhère ; la **norme** est la règle de conduite qui en découle."}]$ex$::jsonb),
  ('0302f027-12d6-50ec-a753-3cf3099a3080'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Daniel, un lien après l’autre","competence":"argumenter","situation":"Daniel, 52 ans, habite Val-Clair (personnage imaginaire). Depuis son licenciement, ses liens sociaux se sont distendus. Le schéma et le portrait permettent d’en faire le bilan.","documents":[{"id":"portrait","type":"texte","genre":"recit","titre":"Le portrait de Daniel","source":"Texte écrit pour l’exercice.","blocs":["Daniel a travaillé vingt-deux ans dans la même entreprise de transport, jusqu’à son licenciement il y a deux ans. Au chômage de longue durée, il ne voit plus ses anciens collègues.","Il ne joue plus aux boules avec ses amis du club : il a honte de sa situation. Son fils, étudiant, lui téléphone chaque dimanche. Daniel vote à toutes les élections et ses droits sont intacts."]},{"id":"socio","type":"schema","titre":"Les liens de Daniel","largeur":340,"hauteur":230,"source":"Trait plein : le lien existe encore. Pointillés : le lien est rompu.","elements":[{"forme":"rect","x":120,"y":90,"l":100,"h":44,"arrondi":10,"texte":"Daniel","teinte":"violet","motif":"plein","id":"z1"},{"forme":"rect","x":10,"y":10,"l":120,"h":40,"arrondi":8,"texte":"Son fils","teinte":"vert","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":210,"y":10,"l":120,"h":40,"arrondi":8,"texte":"Amis du club","teinte":"corail","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":10,"y":175,"l":140,"h":40,"arrondi":8,"texte":"Anciens collègues","teinte":"corail","motif":"clair","id":"z4","zone":true},{"forme":"rect","x":210,"y":175,"l":120,"h":40,"arrondi":8,"texte":"Droits civiques","teinte":"vert","motif":"clair","id":"z5","zone":true},{"forme":"ligne","de":[150,90],"a":[90,50],"teinte":"vert"},{"forme":"ligne","de":[190,90],"a":[250,50],"style":"pointilles","teinte":"corail"},{"forme":"ligne","de":[150,134],"a":[90,175],"style":"pointilles","teinte":"corail"},{"forme":"ligne","de":[190,134],"a":[250,175],"teinte":"vert"}]}],"questions":[{"enonce":"Associe chaque élément du portrait au type de lien décrit par Serge Paugam.","aide":"Filiation = parents-enfants ; élective = amis choisis ; organique = monde du travail ; citoyenneté = même nation.","type":"association","gauche":[{"id":"g0","texte":"Son fils lui téléphone"},{"id":"g1","texte":"Ses amis du club de boules"},{"id":"g2","texte":"Ses anciens collègues"},{"id":"g3","texte":"Il vote, ses droits sont intacts"}],"droite":[{"id":"d0","texte":"Lien de participation élective"},{"id":"d1","texte":"Lien de participation organique"},{"id":"d2","texte":"Lien de citoyenneté"},{"id":"d3","texte":"Lien de filiation"}]},{"enonce":"Touche les deux liens que le schéma montre comme rompus.","aide":"Cherche les traits en pointillés.","type":"zone","document":"socio","multiple":true},{"enonce":"Classe chaque élément : facteur de cohésion sociale ou facteur de fragilisation.","aide":"Pense à ce qui rapproche les gens et à ce qui les met à l’écart.","type":"categories","categories":[{"id":"c0","texte":"Cohésion"},{"id":"c1","texte":"Fragilisation"}],"items":[{"id":"i0","texte":"La ségrégation territoriale"},{"id":"i1","texte":"La vie associative"},{"id":"i2","texte":"L’isolement"},{"id":"i3","texte":"L’emploi stable"},{"id":"i4","texte":"Le chômage de longue durée"},{"id":"i5","texte":"La protection sociale"}]},{"enonce":"Quel est l’effet de la perte de ses liens organique et électif sur Daniel ?","aide":"Les liens sociaux apportent deux choses, selon Paugam.","type":"choix","options":[{"id":"a","texte":"Il change de catégorie socioprofessionnelle"},{"id":"b","texte":"Il gagne en autonomie grâce à plus de temps libre"},{"id":"c","texte":"Il reste pleinement intégré grâce à son droit de vote"},{"id":"d","texte":"Il perd une part de sa protection et de sa reconnaissance"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Le **fils** relève de la filiation, les **amis** de la participation élective (liens choisis), les **collègues** de la participation organique (monde du travail), le **vote** de la citoyenneté."},{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"Les liens avec les **amis du club** et les **anciens collègues** sont rompus (pointillés) ; ceux avec son fils et ses droits civiques subsistent."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"L’**emploi**, la **vie associative** et la **protection sociale** font la cohésion. Le **chômage de longue durée**, l’**isolement** et la **ségrégation territoriale** la fragilisent : Daniel les cumule."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les liens apportent **protection et reconnaissance**. En perdant ses liens de travail et d’amitié, Daniel risque l’isolement : sa **cohésion** avec la société se fragilise."}]$ex$::jsonb),
  ('4bfe56f8-e8ec-5168-b584-89d8e25b0fff'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les chiffres de la ville de Val-Clair","competence":"calculer","situation":"L’observatoire de Val-Clair, ville imaginaire, publie ses données de l’année pour dresser le portrait démographique de la ville.","documents":[{"id":"bilan","type":"tableau","titre":"Bilan de l’année","source":"Chiffres imaginés pour l’exercice.","colonnes":["Donnée","Valeur"],"lignes":[["Population moyenne",25000],["Naissances vivantes",500],["Décès (tous âges)",375],["Décès d’enfants de moins d’un an",2]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nombre de naissances vivantes.","aide":"Lis la ligne « Naissances vivantes ».","type":"zone","document":"bilan","multiple":false},{"enonce":"Calcule le taux brut de natalité de Val-Clair (pour 1 000 habitants).","aide":"Naissances vivantes ÷ population moyenne × 1 000.","type":"nombre","unite":"‰"},{"enonce":"Calcule le taux brut de mortalité (pour 1 000 habitants).","aide":"Décès de l’année ÷ population moyenne × 1 000.","type":"nombre","unite":"‰"},{"enonce":"À quoi rapporte-t-on les décès d’enfants de moins d’un an pour calculer la mortalité infantile ?","aide":"La population « à risque » est celle des enfants nés.","type":"choix","options":[{"id":"a","texte":"À la population totale de la ville"},{"id":"b","texte":"Aux naissances vivantes de l’année"},{"id":"c","texte":"Aux enfants de moins de cinq ans"},{"id":"d","texte":"À l’ensemble des décès de l’année"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Il y a eu **500 naissances vivantes** dans l’année."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 ‰","explication":"500 ÷ 25 000 × 1 000 = **20 ‰**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ‰","explication":"375 ÷ 25 000 × 1 000 = **15 ‰**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le taux de mortalité infantile se calcule en rapportant les décès de moins d’un an aux **naissances vivantes** : 2 ÷ 500 × 1 000 = 4 ‰."}]$ex$::jsonb),
  ('4bfe56f8-e8ec-5168-b584-89d8e25b0fff'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le diabète à Val-Clair : plus de malades, pas plus de nouveaux cas","competence":"lire-graphique","situation":"À Val-Clair (50 000 habitants, ville imaginaire), l’observatoire suit le diabète depuis dix ans. Le nombre de personnes malades augmente, sans que la ville se sente plus « exposée ».","documents":[{"id":"diab","type":"graphique","forme":"barres","titre":"Le diabète à Val-Clair","source":"Chiffres imaginés pour l’exercice.","categories":["2010","2015","2020"],"series":[{"nom":"Nouveaux cas dans l’année","valeurs":[300,300,300],"teinte":"ambre"},{"nom":"Personnes malades à la fin de l’année","valeurs":[2400,2700,3000],"teinte":"violet"}],"axeY":{"titre":"Personnes","min":0,"max":3500,"pas":500},"axeX":{"titre":"Année"}}],"questions":[{"enonce":"Touche l’année où le nombre de personnes malades est le plus élevé.","aide":"Compare les barres de la série « Personnes malades ».","type":"zone","document":"diab","multiple":false},{"enonce":"Quelle est la prévalence du diabète en 2020 ? (part de la population de 50 000 habitants, en %)","aide":"Cas existants ÷ population × 100.","type":"nombre","unite":"%"},{"enonce":"Pourquoi la prévalence augmente-t-elle alors que l’incidence reste stable ?","aide":"L’incidence compte les nouveaux cas, la prévalence tous les cas existants.","type":"choix","options":[{"id":"a","texte":"Le nombre d’habitants de la ville diminue"},{"id":"b","texte":"Il y a chaque année plus de nouveaux cas"},{"id":"c","texte":"Les malades vivent plus longtemps avec la maladie"},{"id":"d","texte":"Le diabète se guérit de plus en plus vite"}],"multiple":false},{"enonce":"Complète les définitions.","aide":"Les nouveaux cas d’un côté, tous les cas de l’autre.","type":"trous","segments":["L’",0," compte les nouveaux cas apparus pendant une période ; la ",1," compte tous les cas existants à un moment donné."],"banque":["prévalence","incidence","mortalité","morbidité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"En **2020**, on compte 3 000 personnes malades : c’est le maximum."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 %","explication":"3 000 ÷ 50 000 × 100 = **6 %**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Avec 300 nouveaux cas par an, mais des malades **qui vivent plus longtemps**, le stock de cas existants grossit : la prévalence augmente à incidence stable."},{"cle":{"type":"trous","trous":[["incidence"],["prevalence"]]},"affichage":"incidence · prévalence","explication":"L’**incidence** mesure les nouveaux cas sur une période ; la **prévalence** mesure l’ensemble des cas (anciens et nouveaux) à un moment donné."}]$ex$::jsonb),
  ('4bfe56f8-e8ec-5168-b584-89d8e25b0fff'::uuid, 3, 3, 15, 50, 5,
