  ('44f70eeb-e15d-5111-8d2e-5fc207d59a59'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La pharmacienne et la chaudière","competence":"analyser-document","situation":"À Val-Clair, ville imaginaire, une pharmacienne remarque quelque chose d’inhabituel. Suis comment une situation locale devient un problème de santé publique.","documents":[{"id":"recit","type":"texte","genre":"article","titre":"Une alerte à Val-Clair","source":"Article imaginé pour l’exercice.","blocs":["Début mars, la pharmacienne Mme Ibrahim remarque, en deux semaines, huit foyers d’un même immeuble qui se plaignent de maux de tête et de nausées. Elle prévient l’agence régionale de santé, dont l’enquête relève une chaudière défectueuse, réparable, et deux hospitalisations.","Un journaliste local publie l’histoire. Une association de locataires réclame des travaux, car les habitants jugent la situation inacceptable. Le maire inscrit la question à l’ordre du jour du conseil municipal."]},{"id":"etapes","type":"chaine","titre":"Du signal à la réponse","disposition":"colonne","noeuds":[{"id":"z1","texte":"Un cas inhabituel est repéré"},{"id":"z2","texte":"Alerte sanitaire"},{"id":"z3","texte":"Enquête épidémiologique"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Mesures et nouvelles règles"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche les quatre mots qui désignent des acteurs faisant émerger le problème (professionnel de santé, médias, association, élu).","aide":"Cherche une profession, un métier de presse, un collectif et un élu.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque fait du récit au critère de reconnaissance d’un problème de santé publique.","aide":"Les critères sont l’ampleur, la gravité, le coût, la possibilité d’agir et la perception sociale.","type":"association","gauche":[{"id":"g0","texte":"Huit foyers d’un même immeuble touchés"},{"id":"g1","texte":"Deux personnes hospitalisées"},{"id":"g2","texte":"Une chaudière réparable"},{"id":"g3","texte":"Des habitants jugent la situation inacceptable"}],"droite":[{"id":"d0","texte":"Perception sociale"},{"id":"d1","texte":"Ampleur"},{"id":"d2","texte":"Possibilité d’agir"},{"id":"d3","texte":"Gravité"}]},{"enonce":"Que faut-il écrire à la place du « ? » dans les étapes ?","aide":"Le maire inscrit la question à l’ordre du jour.","type":"choix","options":[{"id":"a","texte":"Retrait des associations"},{"id":"b","texte":"Fin de la veille sanitaire"},{"id":"c","texte":"Retour à la normale sans suite"},{"id":"d","texte":"Mise à l’agenda politique"}],"multiple":false},{"enonce":"Complète le rôle de l’épidémiologie.","aide":"Elle compte, elle repère, elle identifie.","type":"trous","segments":["L’épidémiologie ",0," le problème : elle mesure la ",1," des cas et repère des facteurs de ",2,"."],"banque":["cache","risque","fréquence","objective"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m45","m51","m65"]},"explication":"La **pharmacienne** (professionnelle de santé), le **journaliste** (médias), l’**association** de locataires et le **maire** (élu) portent le problème."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"Le nombre de foyers donne l’**ampleur**, les hospitalisations la **gravité**, la réparation la **possibilité d’agir**, le jugement des habitants la **perception sociale**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Après l’enquête et la mobilisation des acteurs, la question est portée à l’**agenda politique** : c’est ce qui débouche sur des mesures."},{"cle":{"type":"trous","trous":[["objective"],["frequence"],["risque"]]},"affichage":"objective · fréquence · risque","explication":"L’épidémiologie **objective** le problème : elle mesure la **fréquence** des cas et identifie les facteurs de **risque**. Mais seuls des acteurs le mettent à l’agenda."}]$ex$::jsonb),
  ('44f70eeb-e15d-5111-8d2e-5fc207d59a59'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Rive-Haute : une crise sanitaire en cinq temps","competence":"analyser-document","situation":"Une crise sanitaire éclate à Rive-Haute, ville imaginaire. Tu dois reconnaître ses composantes, puis la replacer parmi les crises qui ont marqué la France.","documents":[{"id":"crise","type":"texte","genre":"article","titre":"Chronique de la semaine","source":"Article imaginé pour l’exercice.","blocs":["En trois jours, 300 habitants de Rive-Haute consultent pour des vomissements et de la diarrhée.","Les experts hésitent : eau du robinet, restaurant collectif ou autre cause ? Les analyses ne sont pas terminées.","Les journaux télévisés ouvrent chaque soir sur l’affaire et les réseaux sociaux s’enflamment.","Des habitants reprochent à la préfecture et à la mairie d’avoir tardé à réagir.","Le préfet doit décider en quarante-huit heures s’il faut interdire l’eau du robinet."]},{"id":"traces","type":"tableau","titre":"Ce que les crises ont laissé","source":"D’après le cours.","colonnes":["Crise","Ce qu’elle a laissé"],"lignes":[["Sang contaminé (années 1980)","Sécurité sanitaire moderne, agences indépendantes"],["Canicule d’août 2003","Plan canicule, registres des personnes vulnérables, journée de solidarité"],["Mediator (2009-2010)","Loi de 2011 sur la sécurité du médicament, création de l’ANSM"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque fait de la chronique à la composante de crise sanitaire qu’il illustre.","aide":"Une crise associe un événement, une incertitude, les médias, une mise en cause et l’urgence.","type":"association","gauche":[{"id":"g0","texte":"300 malades en trois jours"},{"id":"g1","texte":"Les experts hésitent sur la cause"},{"id":"g2","texte":"Les journaux en parlent chaque soir"},{"id":"g3","texte":"Les habitants reprochent aux autorités leur retard"},{"id":"g4","texte":"Le préfet doit trancher en 48 heures"}],"droite":[{"id":"d0","texte":"Mise en cause des autorités"},{"id":"d1","texte":"Pression médiatique"},{"id":"d2","texte":"Incertitude scientifique"},{"id":"d3","texte":"Décision dans l’urgence"},{"id":"d4","texte":"Événement sanitaire"}]},{"enonce":"Pourquoi peut-on parler de crise sanitaire à Rive-Haute ?","aide":"Une crise dépasse les capacités habituelles de réponse.","type":"choix","options":[{"id":"a","texte":"Les autorités n’ont aucune décision à prendre dans l’urgence"},{"id":"b","texte":"Seules 300 personnes sont concernées, ce qui est exceptionnel"},{"id":"c","texte":"Il y a une forte pression médiatique et politique autour de l’événement"},{"id":"d","texte":"Les experts ont immédiatement identifié la cause de l’épidémie"}],"multiple":false},{"enonce":"Touche ce que l’affaire du Mediator a laissé.","aide":"Cherche la loi de 2011.","type":"zone","document":"traces","multiple":false},{"enonce":"Quelle phrase résume le mieux ce que montre le tableau ?","aide":"Regarde la colonne de droite.","type":"choix","options":[{"id":"a","texte":"Une crise n’a presque jamais de conséquence durable sur le système"},{"id":"b","texte":"Les crises sanitaires ne concernent que les médicaments et les vaccins"},{"id":"c","texte":"Seuls les scientifiques décident de ce qui change après une crise"},{"id":"d","texte":"Chaque crise laisse de nouvelles lois, agences ou dispositifs de veille"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g4":"d3","g0":"d4"}},"explication":"Chaque paragraphe illustre une composante : l’**événement** (300 malades), l’**incertitude** (cause inconnue), la **pression médiatique**, la **mise en cause** des autorités et l’**urgence** de la décision."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une **crise sanitaire** associe un événement de santé qui dépasse les capacités habituelles de réponse, une forte dimension **médiatique et politique** et des décisions urgentes."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le Mediator a conduit à la **loi de 2011 sur la sécurité du médicament** et à la création de l’**ANSM**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Chaque crise laisse une trace : **de nouvelles lois, de nouvelles agences, de nouveaux dispositifs de veille**."}]$ex$::jsonb),
  ('eb9922a9-01eb-5960-a702-1f6c4a37cdad'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois situations, trois mots à ne pas confondre","competence":"analyser-document","situation":"Une assistante sociale de Val-Clair, ville imaginaire, présente trois personnes accompagnées par le CCAS. Chacune illustre une notion différente : précarité, pauvreté ou exclusion.","documents":[{"id":"cas","type":"tableau","titre":"Trois personnes accompagnées","source":"Texte écrit pour l’exercice.","colonnes":["Personne","Situation"],"lignes":[["Léa, 24 ans","Elle enchaîne des CDD de trois mois et loge chez une amie en attendant de trouver un appartement."],["Mehdi, 38 ans","Son niveau de vie est inférieur au seuil de pauvreté monétaire de la ville."],["Josette, 70 ans","Veuve, sans domicile depuis un an, elle n’a plus de contact avec sa famille ni avec ses voisins."]],"enteteLignes":true}],"questions":[{"enonce":"Touche la situation d’une personne dont les liens sociaux sont rompus.","aide":"L’exclusion est une rupture des liens.","type":"zone","document":"cas","multiple":false},{"enonce":"Associe chaque personne à la notion qui décrit le mieux sa situation.","aide":"Fragilité, manque, rupture.","type":"association","gauche":[{"id":"g0","texte":"Léa"},{"id":"g1","texte":"Mehdi"},{"id":"g2","texte":"Josette"}],"droite":[{"id":"d0","texte":"Exclusion"},{"id":"d1","texte":"Pauvreté"},{"id":"d2","texte":"Précarité"}]},{"enonce":"Le niveau de vie médian de la ville est de 1 800 € par mois. À combien s’élève le seuil de pauvreté monétaire ?","aide":"Le seuil est fixé à 60 % du niveau de vie médian.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Josette n’a plus de domicile ni de contacts : c’est l’**exclusion**, la rupture des liens sociaux et la mise à l’écart de la vie sociale."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"La **précarité** est une fragilité (emploi et logement incertains), la **pauvreté** un manque de ressources, l’**exclusion** une rupture des liens sociaux."},{"cle":{"type":"nombre","valeur":1080,"tolerance":0},"affichage":"1080 €","explication":"1 800 × 0,60 = **1 080 €** par mois : Mehdi vit sous ce seuil."}]$ex$::jsonb),
  ('eb9922a9-01eb-5960-a702-1f6c4a37cdad'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Intégré, vulnérable ou désaffilié ?","competence":"raisonner","situation":"Dans son mémoire, Nolwenn applique à cinq personnes le continuum de Robert Castel. Elle s’intéresse aussi à la façon dont on glisse d’une zone à l’autre.","documents":[{"id":"zones","type":"tableau","titre":"Cinq situations","source":"Texte écrit pour l’exercice.","colonnes":["Personne","Emploi","Liens sociaux"],"lignes":[["Inès","CDI depuis huit ans","Famille et amis proches"],["Paul","Missions d’intérim","Quelques amis"],["Marc","Sans travail depuis quatre ans","Ne voit plus personne"],["Amina","CDD enchaînés","Famille éloignée, peu d’amis"],["Georges","Retraite stable","Famille et club très présents"]],"enteteLignes":true},{"id":"rup","type":"chaine","titre":"Un parcours d’exclusion","disposition":"ligne","noeuds":[{"id":"z1","texte":"Perte d’emploi"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Perte du logement"},{"id":"z4","texte":"Isolement"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche la personne la plus proche de la désaffiliation.","aide":"Elle cumule absence de travail et isolement.","type":"zone","document":"zones","multiple":false},{"enonce":"Place chaque personne dans la zone de Castel qui lui correspond.","aide":"Intégration : emploi stable et liens solides ; vulnérabilité : emploi précaire, liens fragiles.","type":"categories","categories":[{"id":"c0","texte":"Intégration"},{"id":"c1","texte":"Vulnérabilité"},{"id":"c2","texte":"Désaffiliation"}],"items":[{"id":"i0","texte":"Georges"},{"id":"i1","texte":"Marc"},{"id":"i2","texte":"Inès"},{"id":"i3","texte":"Amina"},{"id":"i4","texte":"Paul"}]},{"enonce":"Quelle étape se place à la place du « ? » dans le parcours d’exclusion ?","aide":"Le cours cite : perte d’emploi, séparation, perte du logement, maladie, isolement.","type":"choix","options":[{"id":"a","texte":"Séparation du couple"},{"id":"b","texte":"Entrée dans un club"},{"id":"c","texte":"Obtention d’un CDI"},{"id":"d","texte":"Hausse du revenu"}],"multiple":false},{"enonce":"Selon Serge Paugam, la disqualification sociale mène : range ses étapes dans l’ordre.","aide":"Du plus léger au plus grave.","type":"ordre","items":[{"id":"a","texte":"Rupture"},{"id":"b","texte":"Dépendance envers les aides"},{"id":"c","texte":"Fragilité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Marc** n’a ni travail ni liens : il est en zone de **désaffiliation**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c1","i4":"c1"}},"explication":"**Inès** et **Georges** ont un emploi ou une retraite stable et des liens solides : **intégration**. **Paul** et **Amina** ont un emploi précaire et des liens fragiles : **vulnérabilité**. **Marc** : **désaffiliation**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’exclusion est un **processus** : perte d’emploi, **séparation**, perte du logement, isolement… des ruptures qui s’alimentent."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"Paugam décrit un parcours de la **fragilité** à la **dépendance** envers les aides, puis à la **rupture**."}]$ex$::jsonb),
  ('eb9922a9-01eb-5960-a702-1f6c4a37cdad'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Comment un problème social est reconnu","competence":"se-reperer-temps","situation":"Au lycée, Mathilde prépare un exposé : « Un problème social est une construction. » Elle dispose d’une frise des réponses publiques et d’une chronique imaginaire.","documents":[{"id":"frise","type":"frise","titre":"Mobilisations et réponses publiques","debut":1950,"fin":2010,"pas":10,"source":"D’après le cours.","evenements":[{"id":"z1","date":1954,"nom":"Appel abbé Pierre"},{"id":"z2","date":1985,"nom":"Restos du cœur"},{"id":"z3","date":1987,"nom":"Rapport Wresinski"},{"id":"z4","date":1988,"nom":"RMI"},{"id":"z5","date":1998,"nom":"Loi exclusions"},{"id":"z6","date":2007,"nom":"DALO"},{"id":"z7","date":2009,"nom":"RSA"}]},{"id":"chron","type":"texte","genre":"article","titre":"Chronique de Val-Clair, en désordre","source":"Chronique imaginée pour l’exercice.","blocs":["Le conseil municipal vote la création d’une aide alimentaire pour les étudiants.","Une association alerte la presse locale : les files d’attente s’allongent.","Chaque semaine, des étudiants font la queue devant l’épicerie solidaire.","La mairie inscrit le sujet à l’ordre du jour du conseil."]}],"questions":[{"enonce":"Touche la prestation qui a remplacé le RMI.","aide":"Elle date de 2009.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la création du RMI de celle du RSA ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque situation à la réponse publique qui l’a suivie.","aide":"Regarde la frise pour les dates.","type":"association","gauche":[{"id":"g0","texte":"Grande pauvreté, rapport Wresinski"},{"id":"g1","texte":"Montée de l’exclusion dans les années 1990"},{"id":"g2","texte":"Mal-logement, mobilisation des associations"}],"droite":[{"id":"d0","texte":"Droit au logement opposable (2007)"},{"id":"d1","texte":"RMI (1988)"},{"id":"d2","texte":"Loi de lutte contre les exclusions (1998)"}]},{"enonce":"Range les phrases de la chronique dans l’ordre où un problème social est reconnu.","aide":"Situation, mobilisation, mise à l’agenda, réponse.","type":"ordre","items":[{"id":"a","texte":"Des étudiants font la queue devant l’épicerie solidaire"},{"id":"b","texte":"La mairie inscrit le sujet à l’ordre du jour"},{"id":"c","texte":"Le conseil municipal vote une aide alimentaire"},{"id":"d","texte":"Une association alerte la presse locale"}]},{"enonce":"Pourquoi une situation difficile n’est-elle pas automatiquement un problème social ?","aide":"Un problème social est une construction.","type":"choix","options":[{"id":"a","texte":"Elle doit toucher plus de la moitié de la population"},{"id":"b","texte":"Elle doit d’abord coûter très cher à l’État"},{"id":"c","texte":"Elle doit être dénoncée et jugée inacceptable par la collectivité"},{"id":"d","texte":"Elle doit être décrite dans un rapport du ministère"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z7"]},"explication":"Le **RSA**, créé en 2009, a remplacé le RMI de 1988."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 ans","explication":"2009 − 1988 = **21 ans**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le rapport Wresinski a mené au **RMI**, la montée de l’exclusion à la **loi de 1998**, le mal-logement au **droit au logement opposable** (DALO, 2007)."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"D’abord la **situation objective**, puis la **mobilisation** (association, presse), la **mise à l’agenda** (ordre du jour) et enfin la **réponse** (aide votée)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un problème social suppose une **situation réelle**, des **acteurs** qui la dénoncent et une **collectivité** qui la reconnaît comme inacceptable."}]$ex$::jsonb),
  ('ab7a2b8c-afe0-5b60-8f38-31d4cc79a925'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quand la vie fait chuter les revenus","competence":"analyser-document","situation":"L’assistante sociale d’un CCAS présente quatre situations courantes à un groupe de lycéens. Chacune correspond à un risque social.","documents":[{"id":"vie","type":"tableau","titre":"Quatre situations","source":"Texte écrit pour l’exercice.","colonnes":["Personne","Situation"],"lignes":[["Karim","Il perd son emploi et cherche un nouveau poste."],["Sophie","Elle attend son premier enfant et prend un congé."],["Odile, 86 ans","Elle ne peut plus faire seule sa toilette ni ses courses."],["Jean","Il se blesse à l’usine pendant son travail."]],"enteteLignes":true}],"questions":[{"enonce":"Touche la situation qui relève du risque de perte d’autonomie.","aide":"Elle concerne une personne âgée.","type":"zone","document":"vie","multiple":false},{"enonce":"Associe chaque personne au risque social auquel elle est exposée.","aide":"Chaque situation fait baisser les revenus ou monter les dépenses.","type":"association","gauche":[{"id":"g0","texte":"Karim"},{"id":"g1","texte":"Sophie"},{"id":"g2","texte":"Odile"},{"id":"g3","texte":"Jean"}],"droite":[{"id":"d0","texte":"Famille"},{"id":"d1","texte":"Perte d’autonomie"},{"id":"d2","texte":"Santé (accident du travail)"},{"id":"d3","texte":"Emploi"}]},{"enonce":"Qu’est-ce qu’un risque social ?","aide":"Pense à l’effet sur le budget d’une personne ou d’une famille.","type":"choix","options":[{"id":"a","texte":"Une prestation versée uniquement aux retraités"},{"id":"b","texte":"Un événement qui ne concerne que les personnes pauvres"},{"id":"c","texte":"Une dépense obligatoire versée à un assureur privé"},{"id":"d","texte":"Un événement qui peut réduire les revenus ou augmenter les dépenses"}],"multiple":false}]}$ex$::jsonb,
