   $ex${"titre":"Bismarck, Beveridge : deux modèles, un système français","competence":"raisonner","situation":"Pour un exposé, Anaïs doit montrer que le système français emprunte aux deux grands modèles historiques. Une frise l’aide à situer les étapes.","documents":[{"id":"frise","type":"frise","titre":"Étapes de la protection sociale","debut":1940,"fin":2025,"pas":5,"source":"D’après le cours.","evenements":[{"id":"z1","date":1942,"nom":"Rapport Beveridge"},{"id":"z2","date":1945,"nom":"Sécurité sociale"},{"id":"z3","date":1991,"nom":"CSG"},{"id":"z4","date":2016,"nom":"PUMa"},{"id":"z5","date":2021,"nom":"Branche autonomie"}]}],"questions":[{"enonce":"Touche la création qui finance la protection sociale par un prélèvement sur l’ensemble des revenus.","aide":"Elle date de 1991.","type":"zone","document":"frise","multiple":false},{"enonce":"Range chaque caractéristique dans le modèle qui lui correspond.","aide":"Bismarck : assurance liée au travail ; Beveridge : universalité financée par l’impôt.","type":"categories","categories":[{"id":"c0","texte":"Modèle bismarckien"},{"id":"c1","texte":"Modèle beveridgien"}],"items":[{"id":"i0","texte":"Financement par cotisations sur les salaires"},{"id":"i1","texte":"Protection de tous les citoyens"},{"id":"i2","texte":"Gestion par les partenaires sociaux"},{"id":"i3","texte":"Gestion par l’État"},{"id":"i4","texte":"Financement par l’impôt"},{"id":"i5","texte":"Prestations proportionnelles aux revenus"},{"id":"i6","texte":"Prestations uniformes"},{"id":"i7","texte":"Protection liée au travail"}]},{"enonce":"Combien d’années séparent la création de la Sécurité sociale de la protection universelle maladie ?","aide":"Lis les dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi dit-on que le système français est mixte ?","aide":"Pense au financement et à l’universalité.","type":"choix","options":[{"id":"a","texte":"Il n’est géré que par l’État, sans partenaires sociaux"},{"id":"b","texte":"Il a abandonné tout