  ('ab7a2b8c-afe0-5b60-8f38-31d4cc79a925'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Où va l’argent de la protection sociale, et qui y accède ?","competence":"raisonner","situation":"À Val-Clair, une conseillère présente la répartition des dépenses de protection sociale, puis une enquête sur le RSA. Elle veut montrer que les droits ne suffisent pas toujours.","documents":[{"id":"dep","type":"graphique","forme":"secteurs","titre":"Dépenses de protection sociale selon le risque","source":"Ordres de grandeur arrondis pour l’exercice.","categories":["Vieillesse et survie","Santé","Famille","Emploi","Logement","Pauvreté et exclusion"],"series":[{"nom":"Part des dépenses","valeurs":[45,35,8,6,3,3]}]},{"id":"rsa","type":"texte","genre":"article","titre":"Une enquête sur le RSA","source":"Enquête imaginée pour l’exercice.","blocs":["À Val-Clair, 100 foyers pourraient toucher le RSA. Seuls 70 le perçoivent.","Parmi les 30 autres, certains ne connaissent pas leur droit, d’autres jugent les démarches trop compliquées, d’autres encore craignent d’être mal regardés."]}],"questions":[{"enonce":"Touche les deux premiers postes de dépenses.","aide":"Cherche les deux plus grandes parts.","type":"zone","document":"dep","multiple":true},{"enonce":"Quelle part des dépenses représentent la santé et la vieillesse-survie réunies ?","aide":"Additionne les deux parts.","type":"nombre","unite":"%"},{"enonce":"Quelle est la part de non-recours au RSA parmi les 100 foyers éligibles ?","aide":"Compte ceux qui ne le perçoivent pas.","type":"nombre","unite":"%"},{"enonce":"Quelles raisons du non-recours apparaissent dans l’enquête ?","aide":"Relis le second paragraphe.","type":"choix","options":[{"id":"a","texte":"Le refus de l’État de verser l’aide"},{"id":"b","texte":"La méconnaissance du droit"},{"id":"c","texte":"Un plafond de ressources dépassé"},{"id":"d","texte":"La complexité des démarches"},{"id":"e","texte":"La crainte d’être stigmatisé"}],"multiple":true},{"enonce":"Que montre le non-recours ?","aide":"Pense au Préambule de 1946 et à l’accès aux droits.","type":"choix","options":[{"id":"a","texte":"La protection sociale est inutile pour les ayants droit"},{"id":"b","texte":"Le RSA est réservé à une minorité de foyers"},{"id":"c","texte":"Les droits sociaux n’existent plus en pratique"},{"id":"d","texte":"Avoir un droit ne suffit pas : il faut pouvoir y accéder"}],"multiple":false}]}$ex$::jsonb,
