   $ex${"titre":"La semaine de la santé de Val-Clair","competence":"analyser-document","situation":"La mairie de Val-Clair, ville imaginaire, affiche le programme de sa semaine de la santé. Chaque action n’agit pas au même moment sur la maladie.","documents":[{"id":"semaine","type":"fiche","modele":"affiche","entete":"Semaine de la santé","sousTitre":"Val-Clair","emoji":"❤️","source":"Texte écrit pour l’exercice.","lignes":[{"texte":"Vaccination gratuite contre la grippe","id":"z1"},{"texte":"Dépistage organisé du cancer du côlon","id":"z2"},{"texte":"Atelier de rééducation après un AVC","id":"z3"},{"texte":"Éducation thérapeutique du patient diabétique","id":"z4"}],"pied":"Entrée libre"}],"questions":[{"enonce":"Touche l’action qui cherche à empêcher l’apparition de la maladie, donc à réduire l’incidence.","aide":"Elle agit avant que la maladie n’apparaisse.","type":"zone","document":"semaine","multiple":false},{"enonce":"Associe chaque action à son niveau de prévention.","aide":"Primaire : empêcher ; secondaire : détecter tôt ; tertiaire : limiter les séquelles.","type":"association","gauche":[{"id":"g0","texte":"Vaccination"},{"id":"g1","texte":"Dépistage organisé"},{"id":"g2","texte":"Rééducation après un AVC"}],"droite":[{"id":"d0","texte":"Prévention secondaire"},{"id":"d1","texte":"Prévention tertiaire"},{"id":"d2","texte":"Prévention primaire"}]},{"enonce":"À quel niveau de prévention relève l’éducation thérapeutique du patient diabétique ?","aide":"Il s’agit de limiter les complications d’une maladie déjà installée.","type":"choix","options":[{"id":"a","texte":"Prévention secondaire"},{"id":"b","texte":"Prévention primaire"},{"id":"c","texte":"Prévention tertiaire"},{"id":"d","texte":"Veille sanitaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La **vaccination** relève de la **prévention primaire** : elle empêche l’apparition de la maladie et réduit l’incidence."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La **vaccination** est primaire, le **dépistage** secondaire (il détecte tôt), la **rééducation** tertiaire (elle limite les séquelles)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Elle vise à limiter les **complications** et les **récidives** d’une maladie déjà installée : c’est de la **prévention tertiaire**."}]$ex$::jsonb),
  ('66085162-3123-5f8a-a1b4-a4edc0f133f6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le programme santé de la mairie, action par action","competence":"analyser-document","situation":"La mairie de Val-Clair finance six actions de santé. Le service municipal veut les ranger selon leur mode d’intervention, puis mesurer la participation au dépistage.","documents":[{"id":"prog","type":"tableau","titre":"Le programme santé de la mairie","source":"Texte écrit pour l’exercice.","colonnes":["Action","Public"],"lignes":[["Piste cyclable reliant les quartiers","Tous les habitants"],["Cantine scolaire équilibrée","Élèves des écoles"],["Atelier sur le sommeil","Lycéens"],["Vaccination contre la grippe en mairie","Personnes âgées"],["Suivi hebdomadaire des cas de grippe","Services de santé"],["Dépistage organisé du cancer du sein","Femmes invitées par courrier"]],"enteteLignes":true},{"id":"bilan","type":"tableau","titre":"Bilan du dépistage","source":"Chiffres imaginés pour l’exercice.","colonnes":["Donnée","Valeur"],"lignes":[["Femmes invitées",2000],["Femmes ayant participé",1100]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque action dans son mode d’intervention.","aide":"La promotion agit sur l’environnement et les conditions de vie ; la veille surveille.","type":"categories","categories":[{"id":"c0","texte":"Veille et sécurité sanitaire"},{"id":"c1","texte":"Promotion de la santé"},{"id":"c2","texte":"Éducation pour la santé"},{"id":"c3","texte":"Prévention"}],"items":[{"id":"i0","texte":"Piste cyclable reliant les quartiers"},{"id":"i1","texte":"Cantine scolaire équilibrée"},{"id":"i2","texte":"Atelier sur le sommeil"},{"id":"i3","texte":"Dépistage du cancer du sein"},{"id":"i4","texte":"Vaccination contre la grippe"},{"id":"i5","texte":"Suivi hebdomadaire des cas de grippe"}]},{"enonce":"Touche l’action qui relève de la veille sanitaire.","aide":"Elle surveille des cas, elle n’en traite pas.","type":"zone","document":"prog","multiple":false},{"enonce":"Quel est le taux de participation au dépistage ?","aide":"Femmes ayant participé ÷ femmes invitées × 100.","type":"nombre","unite":"%"},{"enonce":"Pourquoi créer une piste cyclable relève-t-il de la promotion de la santé ?","aide":"La promotion vise la santé globale et ses déterminants.","type":"choix","options":[{"id":"a","texte":"Elle surveille l’état de santé de la population"},{"id":"b","texte":"Elle cible une maladie précise pour la dépister"},{"id":"c","texte":"Elle remplace les soins pour les malades"},{"id":"d","texte":"Elle agit sur l’environnement et les conditions de vie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c2","i3":"c3","i4":"c3","i5":"c0"}},"explication":"La **promotion** agit sur l’environnement (piste cyclable, cantine), l’**éducation** donne des compétences (atelier), la **prévention** vise une maladie (vaccination, dépistage), la **veille** surveille et détecte les menaces."},{"cle":{"type":"zone","ids":["r4c0"]},"explication":"Le **suivi des cas de grippe** relève de la **veille sanitaire** : surveiller et détecter les menaces."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 %","explication":"1 100 ÷ 2 000 × 100 = **55 %**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **promotion de la santé** donne aux populations les moyens d’améliorer leur santé en agissant sur l’**environnement** et les **conditions de vie**, pas sur une maladie précise."}]$ex$::jsonb),
  ('66085162-3123-5f8a-a1b4-a4edc0f133f6'::uuid, 3, 3, 15, 50, 4,
