  ('7c4e40c4-136d-5912-af28-63f944678f73'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Du monde entier à la rue d’à côté : qui pilote la santé ?","competence":"observer-schema","situation":"Pour un exposé, Inès range les acteurs de la santé par niveau, de l’échelle du monde à celle du quartier.","documents":[{"id":"niveaux","type":"chaine","titre":"Les niveaux de la santé","disposition":"colonne","noeuds":[{"id":"z1","texte":"International"},{"id":"z2","texte":"National"},{"id":"z3","texte":"Régional"},{"id":"z4","texte":"Local"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le niveau où agissent les agences régionales de santé (ARS).","aide":"Leur nom le dit.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Associe chaque acteur à son niveau.","aide":"Du monde à l’échelle du quartier.","type":"association","gauche":[{"id":"g0","texte":"OMS"},{"id":"g1","texte":"Haute Autorité de santé"},{"id":"g2","texte":"Agence régionale de santé"},{"id":"g3","texte":"PMI du département"}],"droite":[{"id":"d0","texte":"Local"},{"id":"d1","texte":"Régional"},{"id":"d2","texte":"National"},{"id":"d3","texte":"International"}]},{"enonce":"Lequel est un acteur de la société civile en santé ?","aide":"Elle n’est ni de l’État, ni d’une agence.","type":"choix","options":[{"id":"a","texte":"Une association de patients"},{"id":"b","texte":"La Haute Autorité de santé"},{"id":"c","texte":"Le ministère de la santé"},{"id":"d","texte":"Une agence régionale de santé"}],"multiple":false}]}$ex$::jsonb,
