   $ex${"titre":"M. Garnier à l’hôpital : ses droits en pratique","competence":"analyser-document","situation":"M. Garnier, personnage imaginaire, est hospitalisé à Val-Clair pour une opération. Plusieurs moments de son séjour mettent en jeu ses droits de patient.","documents":[{"id":"garnier","type":"tableau","titre":"Cinq moments du séjour","source":"Texte écrit pour l’exercice.","colonnes":["N°","Ce qui se passe"],"lignes":[["1","Le chirurgien explique à M. Garnier son opération et ses risques."],["2","M. Garnier demande à lire lui-même son dossier médical."],["3","M. Garnier désigne sa fille pour l’accompagner et être consultée s’il ne peut plus s’exprimer."],["4","Son employeur appelle l’hôpital pour connaître sa maladie : le médecin refuse de répondre."],["5","M. Garnier accepte l’opération après avoir reçu toutes les informations."]],"enteteLignes":true},{"id":"frise","type":"frise","titre":"Lois et institutions de la santé","debut":2000,"fin":2020,"pas":5,"source":"D’après le cours.","evenements":[{"id":"z1","date":2002,"nom":"Loi Kouchner"},{"id":"z2","date":2005,"nom":"Loi Leonetti"},{"id":"z3","date":2010,"nom":"Création des ARS"},{"id":"z4","date":2016,"nom":"Loi Claeys-Leonetti"}]}],"questions":[{"enonce":"Associe chaque moment au droit du patient qu’il illustre.","aide":"Chaque ligne correspond à un droit de la loi du 4 mars 2002.","type":"association","gauche":[{"id":"g0","texte":"Le chirurgien explique l’opération et ses risques"},{"id":"g1","texte":"M. Garnier demande à lire son dossier"},{"id":"g2","texte":"Il désigne sa fille pour l’accompagner"},{"id":"g3","texte":"Le médecin refuse de répondre à l’employeur"},{"id":"g4","texte":"Il accepte l’opération après information"}],"droite":[{"id":"d0","texte":"Consentement libre et éclairé"},{"id":"d1","texte":"Secret professionnel"},{"id":"d2","texte":"Personne de confiance"},{"id":"d3","texte":"Accès au dossier médical"},{"id":"d4","texte":"Droit à l’information"}]},{"enonce":"Touche le moment qui montre le respect du secret professionnel.","aide":"L’employeur n’a pas le droit de savoir.","type":"zone","document":"garnier","multiple":false},{"enonce":"Touche la création qui a donné aux régions leur agence de santé.","aide":"C’est entre 2005 et 2016.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la loi Leonetti de la loi Claeys-Leonetti ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
