  ('7c4e40c4-136d-5912-af28-63f944678f73'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un patient qui devient acteur de sa santé","competence":"analyser-texte","situation":"À Val-Clair, ville imaginaire, un article décrit comment des patients participent aujourd’hui au fonctionnement du système de santé. Un tableau présente les acteurs rencontrés.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Le patient, partenaire de soin","source":"Article imaginé pour l’exercice.","blocs":["À la maison de santé de Val-Clair, un atelier réunit chaque mois des personnes diabétiques. Il est animé par Mme Leroy, patiente experte : elle partage son expérience de la maladie. Les participants choisissent les thèmes abordés.","Des représentants des usagers siègent à la commission des usagers de l’hôpital voisin. De son côté, M. Roux a rédigé ses directives anticipées et désigné sa fille comme personne de confiance."]},{"id":"acteurs","type":"tableau","titre":"Les acteurs rencontrés","source":"Texte écrit pour l’exercice.","colonnes":["Acteur","Ce qu’il fait"],"lignes":[["Agence régionale de santé","Autorise l’ouverture d’un centre de santé"],["Haute Autorité de santé","Évalue la qualité des soins"],["Association de patients","Représente les usagers et les accompagne"],["PMI du département","Suit les bébés et les mamans"],["Maison de santé pluriprofessionnelle","Réunit médecin, infirmière et kinésithérapeute"],["Santé publique France","Surveille les épidémies"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque acteur dans son niveau.","aide":"Les agences nationales couvrent tout le pays ; la PMI est gérée par le département.","type":"categories","categories":[{"id":"c0","texte":"National"},{"id":"c1","texte":"Régional"},{"id":"c2","texte":"Local"},{"id":"c3","texte":"Société civile"}],"items":[{"id":"i0","texte":"Maison de santé pluriprofessionnelle"},{"id":"i1","texte":"Association de patients"},{"id":"i2","texte":"Santé publique France"},{"id":"i3","texte":"Agence régionale de santé"},{"id":"i4","texte":"PMI du département"},{"id":"i5","texte":"Haute Autorité de santé"}]},{"enonce":"Quel est le rôle d’un patient expert comme Mme Leroy ?","aide":"Il s’appuie sur ce qu’il a vécu.","type":"choix","options":[{"id":"a","texte":"Représenter l’assurance maladie auprès des malades"},{"id":"b","texte":"Contrôler la qualité de l’hôpital pour l’État"},{"id":"c","texte":"Prescrire les traitements à la place du médecin"},{"id":"d","texte":"Aider d’autres patients grâce à son expérience de la maladie"}],"multiple":false},{"enonce":"Associe chaque dispositif du texte au principe qu’il illustre.","aide":"Relis le texte.","type":"association","gauche":[{"id":"g0","texte":"La commission des usagers"},{"id":"g1","texte":"L’atelier animé par une patiente experte"},{"id":"g2","texte":"Les directives anticipées"},{"id":"g3","texte":"La personne de confiance"}],"droite":[{"id":"d0","texte":"Démocratie sanitaire"},{"id":"d1","texte":"Accompagner et être consultée"},{"id":"d2","texte":"Volonté sur la fin de vie"},{"id":"d3","texte":"Participation de la personne"}]},{"enonce":"Que change la loi Claeys-Leonetti (2016) pour les directives anticipées ?","aide":"Elle complète la loi Leonetti de 2005.","type":"choix","options":[{"id":"a","texte":"Elles sont rédigées par le médecin seul"},{"id":"b","texte":"Elles deviennent facultatives pour le patient"},{"id":"c","texte":"Elles sont contraignantes pour le médecin"},{"id":"d","texte":"Elles ne concernent plus la fin de vie"}],"multiple":false}]}$ex$::jsonb,
